WITH payload AS (SELECT $archive_payload$[{"id":"ec628755-d19b-51aa-b02d-05517c3af51b","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد شراكة -مغسلة مالبس -قرض -فسخ عقد شركة -تقدير اخلسارة يف الشركة على كل واحد بقدر ماله -عقد الشراكة عقد جائز -إجراء احملاسبة بن الشريكني -إلزام املدعى عليه سداد مبلغ الربح .","document_number":"3424101","case_number":"33647847","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/27","year":"1434","subject":"عقد شراكة -مغسلة مالبس -قرض -فسخ عقد شركة -تقدير اخلسارة يف الشركة على كل واحد بقدر ماله -عقد الشراكة عقد جائز -إجراء احملاسبة بن الشريكني -إلزام املدعى عليه سداد مبلغ الربح .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"   ‫تاريخه‪1434/7/27 :‬هـ َر ْق ُم‬\n                          ‫ُ‬                   ‫َر ْق ُم َّ‬\n                                 ‫الص ِّك‪3424101 :‬‬\n                                  ‫الدعوى‪33647847 :‬‬\n‫رقم قرار التصديق من محكمة االستئناف‪34213795 :‬‬\n                                ‫تاريخه‪1434/5/15:‬هـ‬\n\n\n        ‫عقد شــراكة ‪ -‬مغســلة مالبس ‪ -‬قرض ‪ -‬فســخ عقد شــركة ‪ -‬تقدير‬\n        ‫اخلســارة يف الشــركة علــى كل واحــد بقــدر مالــه ‪ -‬عقــد الشــراكة‬\n        ‫عقــد جائــز ‪ -‬إجــراء احملاســبة بــن الشــريكني ‪ -‬إلــزام املدعــى عليــه‬\n                                                              ‫ســداد مبلــغ الربــح ‪.‬‬\n\n\n\n\n        ‫‪ .1‬قــال يف املغنــى ‪( 131/7‬والشــركة مــن العقــود اجلائــزة تبطــل مبــوت‬\n        ‫احــد الشــريكني وجنونــه وبالفســخ مــن أحدهمــا ألنــه عقــد جائــز‬\n                                                          ‫فبطلــت بذلــك )‪. 1‬ه ـ ‪.‬‬\n        ‫‪ .2‬وقال يف موضع آخر ‪( 145/7‬اخلســران يف الشــركة على كل واحد‬\n        ‫منهمــا بقــدر مالــه فــإن كان مالهمــا متســاويا يف العقــد فاخلســران‬\n                   ‫بينهمــا النصفــن ال نعلــم يف هــذا خــاف بــن أهــل العلــم ) ‪.‬‬\n\n\n\n\n        ‫دعــوى املدعــي ضــد املدعــى عليــه ومضمــون الدعــوى ان املدعــي اتفــق‬\n        ‫مــع املدعــى عليــه علــى االشــتراك يف إنشــاء مغســلة مالبــس مناصفــة‬\n        ‫بــن الطرفــن علــى ان يدفــع املدعــي كافــة التكاليــف ثــم يدفــع‬\n        ‫املدعــى عليــه للمدعــي حصتــه النصــف منهــا بعــد عمــل املغســله وقــرر‬\n        ‫أن املغســلة كلفتــه مبلغ ـ ًا قــدره مائــة وخمســة وخمســون الف ـ ًا وثمامنائــة‬\n\n                                                                                             ‫‪176‬‬\n\f      ‫واربعــة وســتون ريــاال وان املدعــي قــد دفــع كامــل املبلــغ وان املدعــى‬\n      ‫عليــه لــم يدفــع حصتــه منــه النصــف مبلغــا قــدره ســبعة وســبعون ألف ـ ًا‬\n      ‫وتســعمائة واثنــان وثالثــون ريــاال وأن املدعــى عليــه قــام بتشــغيل املغســلة‬\n      ‫واخــذ ايراداتهــا ملــدة اربعــة اشــهر ثــم تبــن للمدعــى فشــل مشــروع‬\n      ‫املغســلة فباعــه بجميــع محتوياتهــا مقابــل مبلغــا قــدره ثمانــون الــف ريــال‬\n      ‫وان حصــة املدعــى عليــه مــن ثمــن البيــع اربعــن الــف ريــال ويخصــم هــذا‬\n      ‫املبلــغ مــن حصــة التكاليــف فيكــون املتبقــى عليــه مبلغــا قــدره ســبعة‬\n      ‫وثالثــون الف ـ ًا وتســعمائة واثنــان وثالثــون ريــا ًال وطلــب إلــزام املدعــى‬\n      ‫عليــه بدفــع هــذا املبلــغ ومحاســبته علــى األربعــة أشــهر التــي قــام املدعــى‬\n      ‫عليــه بتشــغيل املغســلة فيهــا الــزام املدعــى عليــه بدفــع الــف وخمســمائة‬\n      ‫وتســعني ريــاال عبــارة عــن قــرض ســبق ان اقرضــه املدعــي للمدعــى عليــه‬\n      ‫اجــاب املدعــى عليــه باملصادقــة علــى الدعــوى وقــرر املدعــى عليــه انــه‬\n      ‫بعــد جتهيــز املغســلة مت تشــغيلها وبعــد مــدة قــام املدعــى ببيــع املغســلة‬\n      ‫دون علــم املدعــى عليــه وبعــد علمــه بالبيــع وافــق علــى بيــع املغســلة مببلــغ‬\n      ‫مائــة الــف ريــال بشــرط ان ال يتحمــل اى خســارة وأال يدفــع للمدعــي أي‬\n      ‫مبلــغ انكــر املدعــي مــا قــرره املدعــى عليــه وطالــب بدفــع نصــف تكلفة‬\n              ‫املغســلة حســب االتفــاق وقــرر انــه بــاع املغســلة بثمانــن الــف ريــال ‪.‬‬\n      ‫‪ -‬مت اطــاع ناظــر القضيــة علــى عقــد الشــراكة بــن الطرفــن‪ ،‬قــرر‬\n      ‫املدعــى عليــه ان القــرض قــدره ثالثمئــة ريــال فقــط وصادقــه املدعــى‬\n      ‫علــى ذلــك‪ ،‬تصــادق الطرفــان علــى ان املدعــى عليــه كان يقــوم بالعمــل‬\n      ‫باملغســلة مقابــل راتــب شــهري قــدره الفــا ريــال كمــا قــرر املدعــى عليــه‬\n      ‫انــه لــم يدفــع شــيئ ًا مــن رأس املــال حســب االتفــاق وان الثمــن الــذى بــاع‬\n      ‫بــه املدعــي املغســلة يســاوى ثمــن املثــل تقريب ـاً‪ ،‬قــرر ناظــر القضيــة أنــه‬\n\n\n‫‪177‬‬\n\f‫بنــاء علــى مــا هــو مقــرر شــرعا ان عقــد الشــركة عقــد جائــز لــكل‬\n‫مــن الطرفــن فســخه وبعــد اجــراء محاســبته بــن الطرفــن بإضافــة‬\n‫املصاريــف علــى رأس املــال املدفــوع وحصــة الدخــل وثمــن املغســلة‬\n‫وثمــن ســيارة تابعــة للمغســلة مت بيعهــا فيكــون املتبقــى علــى املدعــى‬\n‫عليــه مبلغــا قــدره ســبعة وثالثــون الفــا وســبعون ريــاال املقــرر شــرعا ان‬\n‫اخلســارة يف الشــركة علــى كل واحــد منهمــا بقــدر مالــه فقــد صــدر‬\n‫احلكــم علــى املدعــى عليــه بــأن يســلم للمدعــي املبلــغ املتبقــي عليــه بعــد‬\n‫اجــراء احملاســبة وقــدره ســبعة وثالثــون الفـ ًا وســبعون ريــاال وان يدفــع لــه‬\n‫ثالثمائــه ريــال القــرض الــذي اقــر باقتراضــه وعــدم اســتحقاق املدعي ملا‬\n‫زاد عــن ذلــك ‪ -‬قــرر املدعــي القناعــة‪ ،‬قــرر املدعــى عليــه عــدم القناعــة‪،‬‬\n                                    ‫صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامة مبكة‬\n‫املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة مبكــة املكرمــة برقــم وتاريــخ ‪ 1433/11/10‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 331993590‬وتاريــخ ‪ 1433/11/10‬ه ـ حضــر ‪.....‬‬\n‫بالســجل املدنــي رقــم‪ .....‬وادعــى علــى احلاضــر معــه ‪ ...‬باإلقامــة رقــم‪...‬‬\n‫قائــا يف دعــواه عليــه لقــد اتفقــت مــع املدعــى عليــه هــذا احلاضــر علــى‬\n‫االشــتراك يف إنشــاء مغســلة مالبــس مناصفــة بيننــا علــى أن أدفــع أنــا‬\n‫كافــة التكاليــف ثــم يدفــع لــي حصتــه النصــف منهــا بعــد عمــل املغســلة‬\n‫وقــد كلفــت املغســلة مائــة وخمســة وخمســن ألفــا وثمامنائــة وأربعــة‬\n‫وســتني ريــاال وقــد دفعــت أنــا كامــل هــذا املبلــغ ولــم يدفــع املدعــى عليــه‬\n\n                                                                                        ‫‪178‬‬\n\f      ‫حصتــه منــه النصــف مبلــغ وقــدره ســبعة وســبعون ألفــا وتســعمائة واثنــان‬\n      ‫وثالثــون ريــاال كمــا أنــه قــام بتشــغيل املغســلة وأخــذ إيراداتهــا ملــدة‬\n      ‫أربعــة أشــهر ثــم تبــن لــي فشــل هــذا املشــروع فبعتــه بجميــع محتوياتــه‬\n      ‫مقابــل مبلــغ ثمانــن ألــف ريــال وحصتــه مــن ثمــن البيــع أربعــن ألــف ريــال‬\n      ‫وبخصــم هــذا املبلــغ مــن حصتــه مــن التكلفــة يكــون املتبقــي عليــه‬\n      ‫ســبعة وثالثــن ألفــا وتســعمائة واثنــان وثالثــون ريــال أطلــب إلزامــه بدفــع‬\n      ‫هــذا املبلــغ ومحاســبته علــى األربعــة أشــهر التــي قــام بتشــغيل املغســلة‬\n      ‫فيهــا كمــا أطلــب إلزامــه بدفــع ألــف وخمســمائة وتســعني ريــاال قــرض‬\n      ‫ســبق أن أقرضتــه إياهــا هــذه دعــواي وبســؤال املدعــى عليــه عــن دعــوى‬\n      ‫املدعــي أبــرز إجابتــه بورقــة هــذا نصهــا (ردا علــى مــا ادعــى بــه املدعــي‬\n      ‫شــريكي املواطــن‪ .../‬بأنــه قــال لقــد اتفــق معــي علــى االشــتراك يف‬\n      ‫إنشــاء مغســلة مالبــس مناصف ــة بيننــا علــى أن يدفــع شــريكي املذكــور‬\n      ‫كامــل التكاليــف ثــم أنــا أقــوم بدفــع نصــف التكلفــة مــن نصيبــي‬\n      ‫الشــهري مــن إرادات املغســلة الشــهرية وعلــى احلســابات الصحيحــة‬\n      ‫أن مجمــوع التكلفــة اإلجمالــي الــذي مت جمعهــا أمــام فضيلتكــم‬\n      ‫هــو مبلــغ ( ‪ ) 155.864‬مائــة وخمســة وخمســون ألف ـ ًا وثمامنائــة وأربعــة‬\n      ‫وســتون ريــا ًال وان علــى املذكــور وحســب مــا كان يف العقــد وحســب‬\n      ‫مــا قــدم أمامكــم أن كافــة التكاليــف عليــه هــو ‪ ،‬وهــذا مــا ذكــره‬\n      ‫صحيــح ‪ .‬بعــد التجهيــز مت تشــغيل املغســلة يف ـ ـ ‪1433/7/10‬ه ـ حتــى‬\n      ‫نهايــة ‪ 1433 /10 / 30‬ه ـ وقــام املذكــور ببيــع املغســلة مــن دون علمــي‬\n      ‫وإخبــاري بذلــك كونــي شــريكه يف املغســلة ‪ ،‬وبالرغــم بيننــا عقــد‬\n      ‫بعــدم مقدرتــه ببيــع املغســلة ( صــورة العقــد مرفــق ) علمــا لقــد قــام‬\n      ‫بســرد قصــة لــي أليمــة بأنــه مديــون والنــاس يطالبــوه وانــه محتــاج إلــى‬\n\n\n‫‪179‬‬\n\f‫املــادة لتغطيــة مســتلزمات احليــاة اخلاصــة بــه ‪ ،‬وقــال بــان لديــه زبــون‬\n‫مببلــغ ( ‪ ) 100.000‬مئــة ألــف ريــال وقــام بالترجــي وقــال أنــا مســتعد أن‬\n‫أحتمــل جميــع اخلســائر الناجتــة مــن املغســلة ‪ ،‬وأنــا أقــدرك ولــم أنســاك‬\n‫وإننــي لــم أكــن اعــرف مــا كان مقصــودة هــل يعطينــي شــيء مقابــل‬\n‫األتعــاب التــي قمــت بهــا يف جتهيــز والتســوق واإلشــراف علــى املغســلة‬\n‫ولكــن لــم يحصــل ولــم يخــرج منــه أي شــيء ‪ ،‬وعلــى هــذا قــام ادعــى‬\n‫بأنــه لــم يســتلم إرادات املغســلة مــدة ( ‪ ) 4‬شــهور وكانــت هــذه مــدة‬\n‫العمــل فقــط ‪ ،‬وكيــف أســلمه اإلرادات واحلســابات وهــو لــم يحضــر‬\n‫مــن املدينــة وبالتالــي قمــت مبحاســبة العمــال ومصاريــف املغســلة ‪،‬‬\n‫وقــال بــأن املشــروع فشــل وأنــا اعــرف أن املشــروع لــم يفشــل لقــد بــاع‬\n‫بجميــع محتويــات املغســلة مببلــغ ( ‪) 80.000‬ثمانــن الــف ريــال حســب‬\n‫مــا أدعــى بــه أمامكــم ‪.‬يــا فضيلــة الشــيخ ‪ :‬علمــا أن اإلنســان ال يشــرب‬\n‫املــاء مباشــرة بعــد حفــر البئــر ‪ ،‬وأناشــدكم بــاهلل العلــي القديــر أن‬\n‫تنظــروا يف موضوعــي هــذا بعــن العطــف والرحمــة وحــل موضوعــي‬\n‫بالوجــه الشــرعي ولــذا فإننــي إمنــا وافقــت علــى بيــع املغســلة مبائــة ألــف‬\n‫ريــال بشــرط أن ال أحتمــل أي خســارة وان ال يطالبنــي بشــيء وأنــا لــن‬\n‫ادفــع لــه أي مبلــغ هــذه إجابتــي وبعــرض ذلــك علــى املدعــي قــال أنــا لــم‬\n‫اقــل أن املغســلة تســاوي مائــة ألــف ريــال ولــم أتعهــد لــه بتحمــل اخلســائر‬\n‫وأنــا اطلــب إلزامــه بدفــع نصــف تكلفــة املغســلة حســب االتفــاق بيننــا‬\n‫وأنــا لــم أتعهــد لــه بتحمــل اخلســائر ولــم اقــل لــه أننــي لــن أطالبــك بشــيء‬\n‫وأمــا بيــع املغســلة مبائــة ألــف ريــال فهــذا كان عــرض مــن املشــتري‬\n‫بشــرط أن يكــون املبلــغ مؤجــل ملــدة ســتة أشــهر وقــد وافــق عليــه املدعــى‬\n‫عليــه ولكننــي علمــت أن املشــتري عليــه ديــون فخشــيت أن ال يســدد‬\n\n\n                                                                                          ‫‪180‬‬\n\f      ‫الثمــن فاتفقــت مــع شــخص آخــر علــى بيعــه املغســلة بثمانــن ألــف ريــال‬\n      ‫نقــدا ولــم استشــر املدعــى عليــه يف هــذا البيــع هكــذا قــرر فطلبــت مــن‬\n      ‫الطرفــن العقــد بينهمــا فأبــرز املدعــي ورقــه هــذا نصهــا (عقــد شــراكة‬\n      ‫مجموعــة مغاســل ‪ ...‬اتفــق الطرفــان طــرف أول رقــم الهويــة وطــرف ثانــي‬\n      ‫رقــم اإلقامــة علــى شــراكة محــل مغســلة مببلــغ وقــدره (‪118196‬ريــال)‬\n      ‫مناصفــة بــن الطرفــن علــى الشــروط التاليــة ‪ /1 :‬أن يقــوم الطــرف‬\n      ‫األول باســتخراج الرخــص إذا لــزم األمــر ومتابعــة احلســابات نهايــة كل‬\n      ‫شــهر ‪ /2.‬أن يقــوم الطــرف الثانــي باإلشــراف الكامــل علــى املغســلة‬\n      ‫بــدون تأخيــر ومماطلــة ومحاســبة الطــرف األول نهايــة كل شــهر‬\n      ‫ويســتلم الطــرف الثانــي راتــب (‪2000‬ريــال) شــهري ًا ‪ /3.‬أن يقــوم الطــرف‬\n      ‫الثانــي بســداد الديــن البالــغ ‪59098‬ريــال ) الــذي عليــه لطــرف األول‬\n      ‫مــن نصيبــه الشــهري مــن إيــراد املغســلة‪ /4‬مــدة عقــد الشــراكة بــن‬\n      ‫الطرفــن عشــر ســنوات وال يحــق ألي طــرف مــن الطرفــن أن يفســخ‬\n      ‫العقــد قبــل مــرور خمــس ســنوات يف أي حــال مــن األحــوال ‪ .‬وعلــى ذلــك‬\n      ‫مت التوقيــع ) وبعــرض العقــد علــى املدعــى عليــه صــادق عليــه إ‪.‬ه ـ كمــا‬\n      ‫جــرى ســؤال املدعــى عليــه عــن القــرض الــذي يدعيــه املدعــي فقــال ان له‬\n      ‫بذمتــي قــرض حســن ثالثمائــة ريــال فقــط وليــس لــه بذمتــي ســوى هــذا‬\n      ‫املبلــغ هكــذا قــرر وبعــرض ذلــك علــى املدعــي قــال صحيــح ان املبلــغ‬\n      ‫الــذي أقرضتــه لــه ثالثمائــة ريــال وليــس ألــف وخمســمائة وتســعني ريــال‬\n      ‫هكــذا قــرر فســألت الطرفــن عمــن كان يقــوم بالعمــل يف املغســلة‬\n      ‫فتصادقــا علــى أن املدعــى عليــه كان هــو الــذي يقــوم بتشــغيل املغســلة‬\n      ‫مقابــل راتــب شــهري ألفــي ريــال هكــذا قــرر وبســؤال املدعــى عليــه عــن‬\n      ‫مــدة التشــغيل وعــن دخــل املغســلة ومصاريفهــا خــال مــدة التشــغيل فقال‬\n\n\n‫‪181‬‬\n\f‫املدعى عليه ان مدة تشــغيل املغســلة أربعة أشــهر وإجمالي دخل املغســلة‬\n‫خــال هــذه املــدة أربعــن ألــف وثالثمائــة وخمســة ريــاالت وإجمالــي‬\n‫مصاريــف املغســلة هــي مبلــغ وقــدره واحــد وأربعــون ألف ـ ًا وتســعة عشــر‬\n‫ريــاال مبــا يف ذلــك رواتبــي ورواتــب العمــال وجميــع دخــل املغســلة بحوزتــي‬\n‫اآلن وأنــا مــن صــرف هــذه املصاريــف هكــذا قــرر وبعــرض ذلــك علــى‬\n‫املدعــي قــال أنــا أصادقــه علــى مــا ذكــر مــن مصاريــف ودخــل وال مانــع‬\n‫لــدي مــن إضافــة الباقــي مــن املصاريــف بعــد خصمهــا مــن الدخــل علــى‬\n‫رأس املــال ويقســم بيننــا مناصفــة حســب االتفــاق هكــذا قــرر وبســؤال‬\n‫املدعــى عليــه هــل دفــع شــيئا مــن رأس املــال قبــل شــراء املغســلة او بعــد‬\n‫تشــغيلها فقــال ال لــم ادفــع شــيئا هكــذا قــرر وبســؤال املدعــى عليــه هــل‬\n‫ســلم شــيئا مــن دخــل املغســلة للمدعــي فقــال ال لــم أســلمه شــيئا هكــذا‬\n‫قــرر وجــرى ســؤال املدعــى عليــه هــل الثمــن الــذي بــاع بــه املدعــي املغســلة‬\n‫هــو ثمــن املثــل أم أقــل أم أكثــر فقــال نعــم هــذا ثمنهــا تقريبــا هكــذا‬\n‫قــرر كمــا ســألته هــل دفــع شــيئا مــن رأس مــال املغســلة فقــال أنــا لــم‬\n‫أدفــع شــيئا وجميــع املبالــغ دفعهــا املدعــي ألن االتفــاق بيننــا أن جنمــع‬\n‫كافــة التكاليــف ثــم نقســمها مناصفــة وأدفــع أنــا النصــف مــن دخــل‬\n‫املغســلة هكــذا قــرر ثــم قــرر املدعــي قائــا إننــي بعــت ســيارة أتلفهــا‬\n‫املدعــى عليــه تابعــة للمغســلة مببلــغ ألفــن وأربعمائــة وعشــرين ريــاال‬\n‫فأطلــب إضافــة هــذا املبلــغ هكــذا قــرر وبعــرض ذلــك على املدعــى عليه‬\n‫قــال صحيــح مــا ذكــره املدعــي فقــد بــاع ســيارة تابعــة للمغســلة مببلــغ‬\n‫ألفــن وأربعمائــة وعشــرين ريــاال هكــذا قــرر فبنــاء علــى مــا تقــدم مــن‬\n‫الدعــوى واإلجابــة وألن الطرفــن تصادقــا علــى عقــد الشــركة بينهمــا‬\n‫مناصفــة كمــا أقــر املدعــى عليــه أن املدعــي دفــع كافــة التكاليــف‬\n\n\n                                                                                        ‫‪182‬‬\n\f      ‫وأنــه لــم يدفــع منهــا شــيئا وأن االتفــاق بينهمــا أن يدفــع حصتــه نصــف‬\n      ‫رأس املــال مــن حصتــه مــن الدخــل كمــا أقــر أنــه اقتــرض مــن املدعــي‬\n      ‫ثالثمائــة ريــال وأقــر أن دخــل املغســلة خــال مــدة التشــغيل هــو أربعــون‬\n      ‫ألفــا وثالثمائــة وخمســة ريــاالت ومصاريفهــا واحــد وأربعــن ألفــا وتســعة‬\n      ‫عشــر ريــاال وصادقــه علــى ذلــك املدعــي كمــا أقــر املدعــي أنــه بــاع‬\n      ‫ســيارة تابعــة للمغســلة بألفــن وأربعمائــة وعشــرين ريــاال وصادقــه علــى‬\n      ‫ذلــك املدعــى عليــه كمــا أقــر املدعــى عليــه بــأن الثمــن الــذي بــاع بــه‬\n      ‫املدعــي املغســلة هــو ثمــن املثــل تقريبــا وألن املدعــى عليــه أقــر أنــه لــم‬\n      ‫يدفــع شــيئا مــن رأس املــال وأن املدعــى عليــه هــو الــذي دفعــه وألنــه مــن‬\n      ‫املقــرر شــرعا أن عقــد الشــركة عقــد جائــز لــكل مــن الطرفــن فســخه‬\n      ‫قــال يف املغنــي (‪( )131/7‬والشــركة مــن العقــود اجلائــزة تبطــل مبــوت‬\n      ‫احــد الشــريكني وجنونــه وبالفســخ مــن أحداهمــا ألنــه عقــد جائــز‬\n      ‫فبطلــت بذلــك) أه ـ وبإجــراء احملاســبة بــن الطرفــن بإضافــة املصاريــف‬\n      ‫علــى رأس املــال املدفــوع وخصــم الدخــل وثمــن املغســلة وثمــن الســيارة‬\n      ‫منهــا يكــون املتبقــي علــى املدعــى عليــه مبلــغ وقــدره ســبعة وثالثــون‬\n      ‫ألفــا وســبعون ريــاال وملــا قــرره أهــل العلــم إن الوضيعــة بــن الشــريكني‬\n      ‫علــى قــدر رأس املــال قــال يف املغنــي (‪( )145/7‬اخلســران يف الشــركة‬\n      ‫علــى كل واحــد منهمــا بقــدر مالــه فــان كان مالهمــا متســاويا يف القــدر‬\n      ‫فاخلســران بينهمــا نصفــن ال نعلــم يف هــذا خــاف بــن أهــل العلــم) أه ـ‬\n      ‫لذلــك كلــه فقــد حكمــت علــى املدعــى عليــه بــأن يدفــع هــذا املبلــغ‬\n      ‫ســبعة وثالثــن ألفــا وســبعني ريــاال للمدعــي وأن يدفــع لــه أيضــا ثالثمائــة‬\n      ‫ريــال القــرض الــذي أقــر باقتراضــه منــه وعــدم اســتحقاق املدعــي لبقيــة‬\n      ‫مــا يدعيــه وبعــرض احلكــم علــى الطرفــن قــرر املدعــي قناعتــه باحلكــم‬\n\n\n‫‪183‬‬\n\f‫وقــرر املدعــى عليــه عــدم القناعــة وطلــب رفعــه حملكمــة االســتئناف‬\n‫بعــد تقــدمي الئحــة اعتراضيــة عليــه فأفهمتــه مبراجعــة احملكمــة خــال‬\n‫عشــرة أيــام الســتالم الصــك وتقــدمي الالئحــة االعتراضيــة خــال ثالثــن‬\n‫يومــا مــدة االعتــراض فــإذا تأخــر ســقط حقــه يف طلــب االســتئناف‬\n‫واكتســب احلكــم القطعيــة وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا‬\n                ‫محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/1/26‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ..‬وبعــد ‪،‬ثــم‬\n‫عــادت املعاملــة مــن محكمــة االســتئناف بشــرح فضيلــة الرئيــس برقــم‬\n‫‪1434/5/28 331993590‬هـ على خطاب رئيس محكمة االستئناف‬\n‫مبنطقــة مكــة املكرمــة برقم ‪ 331993590‬يف ‪1434/5/25‬هـ برفقها‬\n‫قــرار التصديــق مبوجــب القــرار رقــم ‪ 34213795‬يف ‪1434/5/15‬ه ـ‬\n‫وهــذا نصــه ‪ -:‬احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد فقــد‬\n‫جــرى منــا نحــن رئيــس وأعضــاء الدائــرة احلقوقيــة الثالثــة يف محكمــة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى هــذا الصــك الصادر‬\n‫مــن فضيلــة الشــيخ ‪ /‬القاضــي باحملكمــة العامــة مبكــة املكرمــة‬\n‫واملســجل بعــدد ‪ 3424101‬وتاريــخ ‪1434/1/27‬ه ـ املتضمــن دعــوى‪...‬‬\n‫ضــد‪ ...‬يف مبلــغ مالــي احملكــوم فيــه مبــا دون باطنــه وبدراســة احلكــم‬\n‫وصــورة ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة علــى احلكــم‬\n‫وبــاهلل تعالــى التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n‫وســلم ‪ ،‬قاضــي اســتئناف ختــم وتوقيــع ‪ ،‬قاضــي اســتئناف ختــم وتوقيــع‬\n‫‪ ،‬رئيــس الدائــرة ختــم وتوقيــع ‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n               ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/6/7‬ه ـ ‪.‬‬\n‫احلمد هلل ‪ ،‬والصالة والســام على رســول اهلل ‪ ،‬وبعد ‪ :‬ـ فقد جرى م ّنا‬\n\n\n                                                                                     ‫‪184‬‬\n\f      ‫نح ــن رئيــس وأعضــاء الدائ ــرة احلقوقي ــة الثالثــة يف محكمــة االســتئناف‬\n      ‫مبنطقــة مكــة املكرمــة االطــاع علــى هــذا الصــك الصــادر مــن‬\n      ‫فضيلــة الشــيخ القاضــي باحملكمــة العامــة مبكــة املكرمــة واملســجل‬\n      ‫بعــدد ‪ 3424101‬وتاريــخ ‪1434/1/27‬ه ـ املتضمــن دعــوى ضــد يف مبلــغ‬\n      ‫مالــي احملكــوم فيــه مبــا دون باطنــه‪ .‬وبدراســة احلكــم وصــورة ضبطــه‬\n      ‫والئحتــه االعتراضيــة تقــررت املوافقــة علــى احلكــم بعــد اإليضــاح‬\n      ‫األخيــر املــؤرخ يف ‪1434/4/17‬ه ـ وبــاهلل تعالــى التوفيــق وصل ــى اهلل‬\n                                 ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪185‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":176,"source_page_end":185,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b65493e7d7ecc795f49fed59e73ad9381f4313e9929aa64ea884e5fdc083df0a","normalized_text_hash":"2e72c7f46baffa339e886d137b51fb94e9ea69d82a874275fbe1c17a311b72dd","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p176-3424101"},{"id":"98dfc2d5-c866-53ce-b02f-1a0dd970ea04","document_type":"judgment","category":"judicial","subcategory":"general","title":"شراكة -استرداد -اتفاق املدعي واملدعى عليه على تنظيم مهرجان مبوجب عقد شراكة -قيام املدعي بتسليم املدعى عليه شيك ا بقيمة معينة -الغاء املهرجان والغاء عقد الشراكة -مطالبة املدعي باسترداد حيازة الشيك -شهادة الشهود للطرفن -تعذر الصلح بن الطرفن -حلف املدعى عليه اليمن -بينات الطرفن غير موصلة -صرف النظر عن الدعوى -إفهام املدعي بأن له مين املدعى عليه على نفي دعواه .","document_number":"3422009","case_number":"33697336","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف باملنطقة الشرقية على املعاملة املقيدة لدى المحكمة ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/25","year":"1434","subject":"شراكة -استرداد -اتفاق املدعي واملدعى عليه على تنظيم مهرجان مبوجب عقد شراكة -قيام املدعي بتسليم املدعى عليه شيك ا بقيمة معينة -الغاء املهرجان والغاء عقد الشراكة -مطالبة املدعي باسترداد حيازة الشيك -شهادة الشهود للطرفن -تعذر الصلح بن الطرفن -حلف املدعى عليه اليمن -بينات الطرفن غير موصلة -صرف النظر عن الدعوى -إفهام املدعي بأن له مين املدعى عليه على نفي دعواه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/1/25 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪3422009 :‬‬\n                        ‫َر ْق ُم الدعوى‪33697336 :‬‬\n‫رقم قرار التصديق من محكمة االستئناف‪34175400 :‬‬\n                          ‫تاريخه‪1434/4/1:‬هـ‬\n\n\n       ‫شــراكة ‪ -‬اســترداد‪ -‬اتفــاق املدعــي واملدعــى عليــه علــى تنظيــم‬\n       ‫مهرجــان مبوجــب عقــد شــراكة‪ -‬قيــام املدعــي بتســليم املدعــى عليــه‬\n       ‫شــيك ًا بقيمــة معينــة‪ -‬الغــاء املهرجــان والغــاء عقــد الشــراكة‪ -‬مطالبــة‬\n       ‫املدعــي باســترداد حيــازة الشــيك‪ -‬شــهادة الشــهود للطرفــن‪ -‬تعــذر‬\n       ‫الصلــح بــن الطرفــن‪ -‬حلــف املدعــى عليــه اليمــن‪ -‬بينــات الطرفــن‬\n       ‫غيــر موصلــة‪ -‬صــرف النظــر عــن الدعــوى‪ -‬إفهــام املدعــي بــأن لــه ميــن‬\n                                                   ‫املدعــى عليــه علــى نفــي دعــواه ‪.‬‬\n\n\n\n\n       ‫‪ .1‬قولــه صلــى اهلل عليــه وســلم (لــو يعطــى النــاس بدعواهــم الدعــى‬\n       ‫نــاس دمــاء رجــال وأموالهــم ولكــن اليمــن علــى املدعــى عليــه) أخرجــه‬\n                                                              ‫البخــاري ومســلم‪.‬‬\n       ‫‪ .2‬قولــه صلــى اهلل عليــه وســلم (البينــة علــى املدعــي واليمــن علــى‬\n                                     ‫املدعــى عليــه) رواه الترمــذي والبيهقــي‪.‬‬\n              ‫‪ .3‬املادة ‪ 4/31‬من نظام املرافعات الشرعية والئحته التنفيذية‪.‬‬\n\n\n\n\n       ‫ادعــى املدعــي وكالــة بــأن موكلــه اتفــق مــع املدعــى عليــه عــن طريــق‬\n       ‫مؤسســته باالشــتراك يف إقامــة مهرجــان تابــع ألمانــة ‪ ....‬ومــن ضمــن‬\n\n                                                                                           ‫‪186‬‬\n\f      ‫بنــود االتفاقيــة أن يســلم موكلــه للمدعــى عليــه مبلغـ ًا وقــدره ســبعمائة‬\n      ‫وخمســون ألــف ريــال كدفعــة أولــى وقــد كتــب شــيكا باملبلــغ املشــار‬\n      ‫إليــه ثــم مت إلغــاء املهرجــان مــن اجلهــة املنظمــة وترتــب علــى ذلــك إلغــاء‬\n      ‫عقــد الشــراكة بــن موكلــه واملدعــى عليــه ثــم جــرى عقــد شــراكة‬\n      ‫آخــر بــن موكلــه واملدعــى عليــه اتفقــوا فيــه علــى املشــاركة يف الريــع‬\n      ‫وعلــى إعــادة الشــيك املذكــور التابــع للعقد الســابق ولكن املدعى عليه‬\n      ‫لــم يعــد الشــيك ملوكلــه ويطلــب إلزامــه باســترداد حيــازة هــذا الشــيك‪،‬‬\n      ‫أجــاب املدعــى عليــه بــأن مــا ذكــره املدعــي غيــر صحيــح وأن الصحيــح‬\n      ‫بأنــه مت االتفــاق مــع مــوكل املدعــي باالشــتراك علــى إدارة املهرجان وأن‬\n      ‫موكلــه هــو املمــول املالــي للمهرجــان وأن العقديــن كل واحــد منهمــا‬\n      ‫مكمــل لآلخــر وال يلغيــه وأنــه لــم يتــم إلغــاء الشــيك وأنــه ســاري املفعــول‬\n      ‫وقــد طالــب بقيمتــه عــدة مــرات وطالــب املــوكل املدعــي تخفيضــه‬\n      ‫وكان بحضــور شــهود ويطلــب إلــزام املدعــي بتســليمه مبلــغ الشــيك‬\n      ‫هكــذا أجــاب‪ ،‬بينــة املدعــي‪ :‬شــاهدان يعمــان لديــه يف املؤسســة‪،‬‬\n      ‫وبينــة املدعــى عليــه‪ :‬شــاهد يعمــل يف أمانــة ‪ ....‬وشــهد بســريان العقديــن‬\n      ‫وســريان مفعــول الشــيك‪ ،‬طعــن بــه املدعــي بــأن بينهمــا خصومــة حيــث‬\n      ‫ســبق أن طعــن يف عرضــه‪ ،‬جــرى إفهــام املدعــي بــأن لــه ميــن املدعــى‬\n      ‫عليــه علــى نفــي دعــواه‪ ،‬لــم يقبــل املدعــي بيمــن املدعــى عليــه‪ ،‬مبــا‬\n      ‫أن املدعــى عليــه أنكــر دعــوى املدعــي ومبــا أن البينــات غيــر موصلــة‬\n      ‫وبنــاء علــى املــادة‪ 4/31‬مــن نظــام املرافعــات الشــرعية ولقولــه صلــى اهلل‬\n      ‫عليــه وســلم (البينــة علــى املدعــي واليمــن علــى املدعــى عليــه )‪ ،‬ومبــا أن‬\n      ‫املدعــي لــم يقبــل بيمــن املدعــى عليــه‪ ،‬صــدر احلكــم بصــرف النظــر‬\n      ‫عــن طلــب املدعــي باســترداد حيــازة الشــيك‪ ،‬وإفهــام املدعــي مبــا يلــي‪:‬‬\n\n\n‫‪187‬‬\n\f‫أوال‪ :‬بــأن لــه ميــن املدعــى عليــه متــى مــا طلبهــا علــى نفــي دعــواه ثاني ـاً‪:‬‬\n‫أن لــه احلــق باملطالبــة يف احملكمــة املختصــة باملوضــوع املالــي للشــيك‬\n‫‪ ،‬اعتــرض املدعــي علــى احلكــم بالئحــة ‪ ،‬صــدق احلكــم مــن الدائــرة‬\n                ‫احلقوقيــة الثانيــة مبحكمــة االســتئناف باملنطقــة الشــرقية‪.‬‬\n\n\n\n\n‫اجلزائيــة‬\n   ‫ّ‬         ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .........‬رئيــس احملكمــة‬\n‫باألحســاء وبنــاء علــى املعاملــة احملالــة إلــى مكتبنــا برقــم ‪33697336‬‬\n‫وتاريــخ ‪1433/12/21‬ه ـ املقيــدة باحملكمة برقــم ‪ 332213420‬وتاريخ‬\n‫‪ 1433/12/21‬هـ ففي يوم الثالثاء املوافق ‪ 1434/01/06‬هـ افتتحت‬\n‫اجللســة الســاعة ‪10 : 30‬وحضــر فيهــا املدعــي وكالــة ‪.........‬ســعودي‬\n‫بالســجل املدنــي رقــم ‪ .........‬مبوجــب الوكالــة الصــادرة مــن كتابــة‬\n‫العــدل الثانيــة باألحســاء برقــم ‪ 33464668‬يف ‪1433/12/22‬ه ـ‬\n‫وادعــى علــى احلاضــر معــه ‪ .........‬ســعودي بالســجل املدنــي رقــم ‪......... :‬‬\n‫ا يف حتريــر دعــواه لقــد اتفــق موكلــي مــع املدعــى عليــه هــذا‬        ‫قائ ـ ً‬\n‫احلاضــر ‪ .........‬عــن طريــق مؤسســته املســماة مؤسســة ‪ .........‬علــى أن‬\n‫يقومــا باالشــتراك فيمــا بينهمــا بتنظيــم مهرجــان تابــع ألمانــة ‪......‬‬\n‫والغرفــة التجاريــة بـ ــ‪ ......‬حتــت مســمى ‪ ......‬ومــن ضمن بنــود هذا االتفاق‬\n‫أن يســلم موكلــي للمدعــى عليــه مبلــغ قــدره ســبعمائة وخمســون ألــف‬\n‫ريـ(‪ )750.000‬ــال كدفعــة أولــى وكتــب لــه موكلــي شــيك ًا بهــذا‬\n‫املبلــغ مســحوب علــى بنــك ‪ .........‬فــرع ‪ .........‬بالهفــوف برقــم ‪ ) 01 ( :‬يف‬\n‫‪1433/06/08‬ه ـ ثــم مت إلغــاء هــذا املهرجــان مــن اجلهــة املنظمــة األمانــة‬\n‫والغرفــة التجاريــة ومت االتفــاق مــع جهــة أخــرى منظمــة وهــي جمعيــة ‪......‬‬\n\n                                                                                          ‫‪188‬‬\n\f      ‫وترتــب علــى ذلــك إلغــاء عقــد الشــراكة املذكــور بني موكلــي واملدعى‬\n      ‫عليــه ثــم متــت كتابــة عقــد شــراكة آخــر بــن موكلــي واملدعــى عليــه‬\n      ‫ليــس فيــه تســليم أي شــيك أو أي مبلــغ وإمنــا اتفقــوا علــى أن يكــون الريــع‬\n      ‫بينهمــا مشــاركة وتضمــن االتفــاق اســتعادة الشــيك املذكــور التابــع‬\n      ‫للعقــد الســابق ملوكلــي ولكــن املدعــى عليــه لــم يســترجع هــذا الشــيك‬\n      ‫ملوكلــي وماطــل موكلــي يف ذلــك حتــى طالــب بقيمــة الشــيك لــدى‬\n      ‫الشــرطة ممــا ترتــب عليــه طلــب موكلــي مــن قبــل الشــرطة واألمــر‬\n      ‫بســجنه وإيقافــه لــذا أطلــب إلــزام املدعــى عليــه باســترداد حيــازة هــذا‬\n      ‫الشــيك هــذه دعــواي وعليهــا أوقــع وبعــرض دعــوى املدعــي وكالــة علــى‬\n      ‫املدعــى عليــه أجــاب عليهــا بقولــه مــا ذكــره املدعــي وكالــة يف دعــواه‬\n      ‫غيــر صحيــح والصحيــح أننــي اتفقــت مــع مــوكل املدعــي باالشــتراك‬\n      ‫علــى إدارة املهرجــان املســمى مهرجــان «فرحــة حســانا « الــذي ذكــره‬\n      ‫املدعــي وكالــة وأن املمــول املالــي هــو مــوكل املدعــي ‪.........‬مبوجــب‬\n      ‫العقــد يــن املذكوريــن يف دعــوى املدعــي ولــم نتفــق علــى إلغــاء العقــد‬\n      ‫األول بــل كل منهمــا مكمــل لآلخــر كمــا لــم يتــم إلغــاء الشــيك الــذي‬\n      ‫ذكــره املدعــي وكالــة بــل مــا زال ســاري املفعــول وقــد طالبــت بقيمتــه‬\n      ‫عــدة مــرات وجلســت مــع مــوكل املدعــي عــدة جلســات للمصاحلــة‬\n      ‫بحضــور شــهود لتســليم مبلــغ الشــيك مــن قبــل مــوكل املدعــي ولــم‬\n      ‫ينكــر مبلــغ الشــيك وإمنــا طلــب تخفيــض املبلــغ مــع املبالــغ األخــرى التــي‬\n      ‫عليــه وبنــاء علــى ذلــك فإننــي أطالــب بإلــزام مــوكل املدعــي تســليم مبلــغ‬\n      ‫الشــيك وهــو مــا زال ســاري املفعــول ولــم يتــم إلغــاءه وقدمــت دعــوى‬\n      ‫مطالبــة بذلــك لــدى الشــرطة واملدعــى عليــه مطالــب لــدى الشــرطة‬\n      ‫بســبب هــذا الشــيك هكــذا أجــاب ‪ ،‬وبــرد إجابــة املدعــى عليــه علــى‬\n\n\n‫‪189‬‬\n\f‫املدعــي وكالــة قــرر بقولــه ال صحــة ملــا ذكــره املدعــى عليــه أن العقدين‬\n‫ســاريني ومكملــن لبعضهمــا وإنــه لــم يتــم إلغــاؤه العقــد األول منهمــا‬\n‫والصحيــح مــا ذكرتــه يف دعــواي هكــذا قــرر ثــم جــرى ســؤال املدعــي‬\n‫وكالــة عــن موضــوع إلغــاء الشــيك ومطالبــة موكلــه باســترداده مــن‬\n‫املدعــى عليــه ولكنــه امتنــع وهــل لديــه بينــة علــى ذلــك فقــرر بقولــه نعــم‬\n‫يوجــد لــدي شــاهدين مــن عمــال املؤسســة هكــذا قــرر ويف جلســة أخرى‬\n‫حضــر املدعــي أصالــة ‪.........‬ســعودي بالســجل املدنــي رقــم ‪......... :‬كمــا‬\n‫حضــر املدعــى عليــه ‪ .........‬فجــرى عــرض الدعــوى ومــا قــرره وكيــل‬\n‫املدعــي يف اجللســة الســابقة علــى املدعــي أصالــة يف هــذه اجللســة فصــادق‬\n‫علــى جميــع مــا ذكــره وكيلــه ثــم قــرر بقولــه أحضــرت معــي شــهودي‬\n‫اآلن هكــذا قــرر ثــم جــرى طلــب أحــد الشــهود فحضــر ‪......... /‬ســعودي‬\n‫بالســجل املدنــي رقــم ‪......... :‬املشــار فيهــا إلــى أنــه مــن مواليــد‬\n‫‪1405/12/11‬ه ـ وبســؤاله عــن عملــه وصلتــه بطــريف الدعــوى ومــا عنده‬\n‫مــن شــهادة قــرر بقولــه أننــي أعمــل موظــف يف جامعــة امللــك فيصــل كما‬\n‫أعمــل بعــد دوامــي احلكومــي لــدى مؤسســة املدعــي ‪.........‬كعمــل‬\n‫إضــايف وال تربطنــي أي صلــة قرابــة باملدعــي وال املدعــى عليــه والــذي‬\n‫عنــدي مــن الشــهادة هــو أننــي علــى علــم تــام مبوضــوع شــراكة املدعــي‬\n‫مــع املدعــى عليــه لكونــي أعمــل يف مؤسســة املدعــي ‪.........‬وكنــت‬\n‫أحتــدث مــع املدعــى عليــه بشــكل دائــم عنــد مراجعتــه للمؤسســة وقــد‬\n‫حضــرت كتابــة عقــد االتفــاق الثانــي بينهمــا ولكــن لــم أحضــر كتابــة‬\n‫العقــد األول وقــد كنــت علــى علــم بــه وقــد مت تســليم مبلــغ مائتــن‬\n‫وخمســن ألــف ريـ(‪ )250.000‬ــال للمدعــى عليــه كجــزء مــن اتفــاق‬\n‫العقــد األول وبعــد إلغــاء االتفــاق األول كنــت أتناقــش مــع املدعــى عليــه‬\n\n\n                                                                                       ‫‪190‬‬\n\f      ‫عنهــا بخصــوص اســترجاعها ثــم مت االتفــاق معــه علــى أن يتــم حســابها‬\n      ‫مــن مصاريــف العقــد لتشــغيل املهرجــان ثــم تخصــم عليــه مــن عقــد‬\n      ‫التشــغيل وبالنســبة للشــيك فقــد مت الســكوت عنــه بحكــم أن ا التفــاق‬\n      ‫األول لــم يتــم وأنــه جــرى تغييــر العقــد هــذا مــا لــدي وبــه أشــهد هلل تعالــى‬\n      ‫ثــم حضــر الشــاهد الثانــي وهــو ‪.........‬مصــري اجلنســية مبوجــب رخصــة‬\n      ‫اإلقامــة رقــم ‪......... :‬املشــار فيهــا إلــى أنــه مــن مواليــد ‪1983/08/14‬م‬\n      ‫وبســؤاله عــن عملــه وعــن صلتــه بالطرفــن ومــا لديــه مــن شــهادة قــرر‬\n      ‫بقولــه أننــي أعمــل محاســب لــدى مؤسســة «‪».........‬التابعــة للمدعــي‬\n      ‫‪.........‬وبحكــم عملــي لــدى املؤسســة كنــت أعلــم عــن اتفــاق املدعــي مــع‬\n      ‫املدعــى عليــه بخصــوص تشــغيل ملهرجــان « فرحــة حســانا « وقد حضرت‬\n      ‫اجتماع ـ ًا بــن املدعــي واملدعــى عليــه وشــخصني آخريــن وممــا جــرى‬\n      ‫الــكالم عنــه مبلــغ مائتــن وخمســن ألــف ريـ(‪ )250.000‬ــال وكان‬\n      ‫احلديــث عــن تســديد هــذا املبلــغ ثــم اتفقــوا علــى أن تخصــم مــن مبلــغ‬\n      ‫التشــغيل للمهرجــان بعــد انتهــاء املهرجــان وأن هــذا املبلــغ هــو عبــارة عــن‬\n      ‫دفعــة أولــى ســلمت مــن ‪.........‬لــأخ ‪.........‬كدفعــة أولــى مــن مبلــغ الشــيك‬\n      ‫املتفــق عليــه يف العقــد األول هــذا مــا لــدي وبــه أشــهد ثــم جــرى عــرض‬\n      ‫الشــاهدين وشــهادتهما علــى املدعــى عليــه فقــرر بقولــه أمــا الشــاهدان‬\n      ‫فأنــا ال أعرفهمــا ســوى أنــي قابلتهمــا يف مؤسســة األخ ‪.........‬ألنهمــا‬\n      ‫يعمــان يف املؤسســة وأمــا شــهادتهما فغيــر صحيحــة وقــد أشــار أحــد‬\n      ‫الشــهود يف شــهادته عــن حضــور شــخص أنــا أطالــب بحضــوره وهــو‬\n      ‫األخ‪........./‬بصفتــه مديــر ًا للمهرجــان هكــذا قــرر ثــم قــرر بقولــه يوجــد‬\n      ‫لــدي ورقــة أطلــب إرفاقهــا باملعاملــة كتبــت فيهــا إجابــة ورد تتعلــق‬\n      ‫بالدعــوى والشــهود وقــد مت إرفاقهــا باملعاملــة ثــم جــرى ســؤال املدعــي‬\n\n\n‫‪191‬‬\n\f‫هــل لديــك زيــادة بينــة فقــرر بقولــه العقــد الثانــي الــذي بينــي وبــن‬\n‫املدعــى عليــه ينــص علــى األربــاح التــي لنــا ولهــم هــي مناصفــة بيننــا مــن‬\n‫دخــل املهرجــان وال يوجــد منهــا أي مبالــغ أو شــيكات بــل جــاء النــص يف‬\n‫العقــد صريحـ ًا علــى أن مبلــغ املائتــن وخمســن ألــف ريـ(‪ )250.000‬ــال‬\n‫تخصــم مــن مســتحق املدعــى عليــه ملؤسســتنا هكــذا قــرر ثــم قــرر‬\n‫املدعــى عليــه بقولــه أن هــذا املبلــغ ال يعنينــي ماليـ ًا وإمنــا موضــوع الدعــوى‬\n‫يف الشــيك وقــد ســلمه لــي بإرادتــه واختيــاره وأقــر بصحتــه لــدى الشــرطة‬\n‫أثنــاء التحقيــق وكذلــك عنــد األمــارة وأطلــب الرجــوع إلــى دفتــر‬\n‫التحقيــق إلثبــات ذلــك ثــم قــرر املدعــي بقولــه أمــا اعتــرايف الــذي ذكــره‬\n‫املدعــى عليــه يف الشــرطة فهــو ليــس اعتــراف وإمنــا هــو عبــارة وصــف‬\n‫حــال وأمــا مــا ذكــره عــن االعتــراف يف األمــارة فهــو ليــس اعتــراف وإمنــا‬\n‫أنــا قدمــت شــكوى لطلــب رد حيــازة الشــيك وهــم بدورهــم قامــوا برفعــه‬\n‫للشــرطة هكــذا قــرر وحيــث األمــر مــا ذكــر جــرى الرجوع إلــى املعاملة‬\n‫فوجــدت مــن بــن طياتهــا دفتــر التحقيــق املرفــق رقــم ‪)3338801027( :‬‬\n‫لفــة رقــم ‪ )1( :‬وعلــى الصحيفــة رقــم ‪ )11( :‬مت توجيــه ســؤال للمدعــي‬\n‫‪.........‬هــذا نصــه واإلجابــة عليــه (س‪ /‬تقــدم املدعــو‪......... /‬وكيــل‬\n‫شــرعي عــن مؤسســة ‪.........‬ببــاغ ضــدك حــال قيامــك بتحريــر شــيك‬\n‫بــدون رصيــد مببلــغ ســبعمائة وخمســون ألــف ريــال فمــا قولــك ج‪ /‬نعــم مت‬\n‫ذلــك ومت تســديد مبلــغ مائتــان وخمســون ألــف ريــال مــن أصــل الشــيك )‬\n‫ثــم جــرى عــرض ذلــك علــى املدعــي فقــرر بقولــه نعــم هــذا صحيــح وهــو‬\n‫كمــا ذكــرت وصــف حــال وليــس إقــرار فأنــا كتبــت هــذا الشــيك‬\n‫ا ولكــن مت إلغــاؤه باتفاقنــا معــه علــى ذلــك وعلــى اســترداده ولكنه‬         ‫فعـ ً‬\n‫لــم يفعــل والدليــل هــو تســليم املبلــغ املذكــور وهــو مائتــن وخمســن ألــف‬\n\n\n                                                                                          ‫‪192‬‬\n\f      ‫ريـ(‪ )250.000‬ــال واســتعداده باســترجاعها أو حســابها عليــه مــن أربــاح‬\n      ‫املهرجــان هكــذا قــرر ثــم قــرر املدعــى عليــه بقولــه يوجــد خطــاب يف‬\n      ‫املعاملــة مقــدم مــن املدعــي ‪.........‬لألميــر يطلــب فيــه مهلــة خمســة‬\n      ‫وأربعــون يوم ـ ًا بشــفاعة مــن الدكتــور‪ ......... /‬والشــيخ‪......... /‬فوجــه‬\n      ‫األخيــر بإعطــاء مهلــة أربعــة عشــر يوم ـ ًا وأنــه إذا لــم يســدد فيتخــذ‬\n      ‫اإلجــراءات الالزمــة وأطلــب الرجــوع لــه مــن املعاملــة هكــذا قــرر‬\n      ‫وبعــرض ذلــك علــى املدعــي قــرر بقولــه أن هــذا اخلطــاب موجــود ولكنــه‬\n      ‫ليــس مقدم ـ ًا مــن عنــدي وإمنــا قدمــه أخــواي ‪.........‬و‪ .........‬يطلبــون‬\n      ‫الشــفاعة باملهلــة وأنــا لــم أوقــع عليــه هكــذا قــرر ثــم قــرر املدعــى عليــه‬\n      ‫بقولــه أن األميــر طلــب التحقــق يف املوضــوع لــدى الشــرطة هــل هــو‬\n      ‫صحيــح أم ال فتبــن صحتــه وبنــاء علــى ذلــك خــرج مــن الشــرطة األخ‬\n      ‫‪.........‬هكــذا قــرر ثــم قــرر املدعــي بقولــه أن هــذا اخلطــاب يعتبــر شــفاعة‬\n      ‫إلخراجــي مــن التوقيــف وال يعتبــر إدانــة لــي أو إثبــات علــي هكــذا قــرر‬\n      ‫ثــم قــرر املدعــى عليــه بقولــه يوجد لــدي شــاهدين أحدهمــا ‪.........‬والثاني‬\n      ‫الشــيخ ‪ .........‬ومســتعد بإحضارهمــا وأطلــب حتديــد موعــد لذلــك قريــب‬\n      ‫هكــذا قــرر ويف جلســة أخــرى حضــر املدعــي واملدعــى عليــه وقــرر‬\n      ‫املدعــى عليــه بأنــه احضــر شــاهد واحــد ًا و بطلبــه حضــر ‪ ».........‬ســعودي‬\n      ‫« مبوجــب الســجل املدنــي رقــم (‪ ).........‬مواليــد عــام ‪1395‬ه ـ وبســؤاله‬\n      ‫عــن عملــه وصلتــه بطــريف الدعــوى و مــا لديــه مــن شــهادة قــرر بقولــه‬\n      ‫أعمــل يف أمانــة ‪ ..........‬وال تربطنــي بالطرفــن أي صلــة قرابــة أو عمــل‬\n      ‫وإمنــا عرفتهــم مــن خــال مهرجــان ‪ ..........‬بحكــم عملــي يف أمانــة ‪..........‬‬\n      ‫كمديــر للمهرجــان مــن قبــل األمانــة ومنســق للجهــات املتعاقــدة مــع‬\n      ‫األمانــة والــذي لــدي مــن الشــهادة هــو أننــي بحكــم عملــي يف أمانــة‬\n\n\n‫‪193‬‬\n\f‫‪ ..........‬و إدارتــي و إشــرايف علــى املهرجــان حضــرت مــع الطرفــن كتابــة‬\n‫العقديــن الــذي بينهمــا بخصــوص اتفاقهمــا علــى القيــام بــإدارة وتشــغيل‬\n‫املهرجــان املســمى فرحــة حســانا والــذي أعرفــه أن العقديــن كالهمــا‬\n‫ســاريي املفعــول وأن العقــد الثانــي كتــب علــى أســاس خيمــة التســوق‬\n‫بعــد اختالفهمــا علــى إدارة هــذه اخليمــة وقــد كتــب العقــد الثانــي ألجــل‬\n‫حــل مشــكلة اخليمــة فقــط كمــا أننــي أشــهد بــأن الشــيك املكتــوب‬\n‫مــن قبــل ‪ .........‬لـ ــ‪......... .........‬مببلغ ســبعمائة وخمســن ألف ريال ســاري‬\n‫املفعــول ولــم يتــم إلغــاءه هــذا مــا لــدي وبــه أشــهد ثــم جرى ســؤال الشــاهد‬\n‫عــن معرفتــه عــن ســريان مفعــول الشــيك فقــرر بقولــه هــذا معــروف مــن‬\n‫تاريخــه كمــا أننــي حضــرت حتريــر الشــيك وتســليمه مــن قبــل األخ‬\n‫‪.........‬لــأخ ‪.........‬وجلســنا عــدة جلســات ألجــل الصلــح بــن الطرفــن ولــم‬\n‫يتــم إلغــاء الشــيك أو حتــى طلبــه مــن قبــل األخ ‪.......‬و ألجــل ذلــك فانــه‬\n‫يكــون ســاري املفعــول هكــذا قــرر ثــم جــرى عــرض الشــاهد وشــهادته‬\n‫علــى املدعــي فقــرر بقولــه أوال أنــا أطالــب مبخاطبــة أمانــة األحســاء هــل‬\n‫مت تنفيــذ مهرجــان ‪ ..........‬و أنــه مت كتابــة عقــد مــع األمانــة لتنظيــم‬\n‫املهرجــان مــع مؤسســة رتــاج ألن األمانــة لــم تقــم بذلــك ولــو تبــن أن‬\n‫األمانــة قامــت بذلــك أنــا مســتعد أتنــازل عــن الدعــوى أمــا مــن حيــث‬\n‫الشــاهد فأنــا اطعــن فيــه ألنــه ســبق أن طعــن يف عرضــي و يف عــرض‬\n‫والدتــي وعنــدي البينــة علــى ذلــك أمــا الشــهادة فهــي غيــر صحيحــه‬\n‫والشــاهد لــم يحصــل أن اجتمــع مــع مؤسســتنا و أمنــا دائمــا يجتمــع مــع‬\n‫مؤسســة املدعــى عليــه وجميــع اجلوائــز الــذي يتســلمها مــن الرعــاة‬\n‫يأخذهــا ويســلمها ملؤسســة ‪.......‬اخلاصــة باملدعــى عليــه ولــم يســلم لنــا‬\n‫وال هديــه واحــدة كمــا أنــه ينــزل اإلعالنــات ويضــع فيهــا اســم جميــع‬\n\n\n                                                                                        ‫‪194‬‬\n\f      ‫رعــاة املهرجــان عــدا املنظــم الرئيســي وهــو مؤسســتنا وهــذا يــدل علــى‬\n      ‫انحيــازه مــع مؤسســة املدعــى عليــه ‪.......‬وكان يســتدعي بعــض‬\n      ‫املســتأجرين و يســلم مبالــغ اإليجــار ملؤسســة املدعــى عليــه ‪ .......‬ولــم‬\n      ‫يســلم لنــا شــيء ونحــن املنظمــون األساســيون هكــذا قــرر ثــم قــرر‬\n      ‫الشــاهد بقولــه لــو أنــي لــم أكــن مديــرا كيــف يقــر اآلن بأننــي اتولــى‬\n      ‫اإلعالنــات واســتالم اإليجــارات وتأجيرهــا ملؤسســة ‪ .......‬ثــم قــرر‬\n      ‫الشــاهد بقولــه أننــي أديــت مــا عنــدي مــن شــهادة ثــم جــرى عــرض‬\n      ‫الصلــح علــى الطرفــن وترغيبهمــا فيــه فاســتعدا باملفاهمــة بينهمــا ألجــل‬\n      ‫الصلــح ويف جلســة أخــرى حضــر املدعــي‪....... /‬واملدعــى عليــه‪....... /‬‬\n      ‫وبســؤال الطرفــن عــن الصلــح قــررا بأنــه لــم يتــم بينهمــا الصلــح ثــم جرى‬\n      ‫ســؤال الطرفــن هــل لديهمــا زيــادة بينــات فقــرر املدعــى عليــه ليــس لــدي‬\n      ‫ســوى مــا قدمتــه وأنــا مســتعد بحلــف اليمــن أن الشــيك ســاري املفعــول‬\n      ‫ولــم يتــم إلغــاؤه هكــذا قــرر ثــم قــرر املدعــي بقولــه أنــه مــا زال عنــدي‬\n      ‫بينــات وهــي أن مبلــغ املائتــن وخمســن ألــف ريـ(‪ )250.000‬ــال جــزء مــن‬\n      ‫مبلــغ الشــيك اســتلمها املدعــى عليــه منــي بإيداعهــا يف حســاب املدعــى‬\n      ‫عليــه وهــي بينــي واملدعــى عليــه لــم يجــاوب عليهــا وأطلــب إجابتــه عليهــا‬\n      ‫قبــل حلفــه اليمــن هكــذا قــرر وبعــرض ذلــك علــى املدعــى عليــه قــرر‬\n      ‫بقولــه أنــا مســتعد باإلجابــة علــى ذلــك لكــن ال أرغــب يف إطالــة الدعــوى‬\n      ‫وتأخيرهــا وأطلــب إنهاؤهــا أمــا بخصــوص مبلــغ املائتــن وخمســن ألــف‬\n      ‫ريـ(‪ )250.000‬ــال فما ذكره املدعي بخصوصها صحيح فقد اســتلمت‬\n      ‫مــن املدعــي مبلــغ مائتــن وخمســن ألــف ريـ(‪ )250.000‬ــال مــن قيمــة‬\n      ‫الشــيك املذكــور ومت إيداعهــا يف حســابي وأنــا ال أنكــر ذلــك ولكــن‬\n      ‫هــذا املبلــغ املائتــن وخمســن ألــف ريـ(‪ )250.000‬ــال مت ترحيلهــا إلــى‬\n\n\n‫‪195‬‬\n\f‫خيمــة التســوق وعلــى أنهــا تكــون جــزء مقــدم مــن املبالــغ املســتحقة لــي‬\n‫ا ومبالــغ أخــرى غيرهــا مــن كامــل مســتحقاتي‬      ‫مــع مبلــغ الشــيك كامـ ً‬\n‫يف عقــد التشــغيل للمهرجــان املذكــور وقــد مت ذكرهــا يف العقــد بأنــه‬\n‫يتــم خصــم مبلــغ مائتــن وخمســن ألــف ريـ(‪ )250.000‬ــال مــن املبالــغ‬\n‫املســتحقة لــي مــن كامــل العقــد وعلــى ذلــك فــإن الشــيك مــا زال ســاري‬\n‫املفعــول ولــم يتــم إلغــاؤه وأنــا أطالــب بقيمتــه هكــذا قــرر ثــم قــرر املدعي‬\n‫بقولــه إقــرار املدعــى عليــه مببلــغ املائتــن وخمســن ريـ(‪ )250.000‬ــال‬\n‫يــدل علــى إلغــاء الشــيك ونــص العقــد الثانــي يؤكــد ذلــك هكــذا قــرر‬\n‫ثــم قــرر املدعــى عليــه بقولــه ال صحــة ملــا ذكــره املدعــي والصحيــح مــا‬\n‫ذكرتــه هكــذا قــرر ثــم جــرت املفاهمــة بــن الطرفــن علــى إعــادة‬\n‫موضــوع الصلــح بينهمــا تالفي ـ ًا حللــف اليمــن ويف جلســة أخــرى حضــر‬\n‫املدعــي أصالــة ‪.......‬كمــا حضــر املدعــى عليــه ‪.......‬وجــرى نصــح‬\n‫الطرفــن وترغيبهمــا يف الصلــح وترهيبهمــا مــن حلــف األميــان وبعــد‬\n‫مداولــة ومفاهمــة لــم يقبــل الطرفــان بــأي صلــح ثــم جــرى إفهــام املدعــى‬\n‫عليــه بــأن عليــه حلــف اليمــن الشــرعية علــى نفــي دعــوى املدعــي مــن أنــه‬\n‫لــم يتفــق مــع املدعــي علــى اســترجاع الشــيك محــل الدعــوى لــه بعــد إلغاءه‬\n‫بينهمــا فاســتعد بحلــف اليمــن وبعــرض ذلــك علــى املدعــي قــرر عــدم‬\n‫قبــول ميــن املدعــى عليــه وحيــث األمــر مــا ذكــر وبنــاء علــى مــا تقــدم‬\n‫مــن الدعــوى واإلجابــة وحيــث أن املدعــي يطالــب باســترداد حيــازة‬\n‫الشــيك محــل الدعــوى مــن املدعــى عليــه لكونــه مت إلغــاؤه واالتفــاق مــع‬\n‫املدعــى عليــه علــى اســترجاعه لــه وحيــث أنكــر املدعــى عليــه دعــوى‬\n‫املدعــي وحيــث أن مــا أحضــره املدعــي واملدعــى عليــه مــن بينــات غيــر‬\n‫موصلــة وبنــاء علــى املــادة (‪ )4/31‬مــن اللوائــح التنفيذيــة مــن نظــام‬\n\n\n                                                                                        ‫‪196‬‬\n\f      ‫املرافعــات الشــرعية ولقــول الرســول صلــى اهلل عليــه وســلم ‪ ( :‬لــو يعطــى‬\n      ‫النــاس بدعواهــم الدعــى نــاس دمــاء رجــال وأموالهــم ولكــن اليمــن‬\n      ‫علــى املدعــى عليــه ) [رواه البخــاري ومســلم] ولقولــه صلــى اهلل عليــه‬\n      ‫وســلم ‪ ( :‬البينة على املدعي واليمني على املدعى عليه ) [رواه الترمذي‬\n      ‫والبيهقــي] وحيــث اســتعد املدعــى عليــه بحلــف اليمــن الشــرعية علــى‬\n      ‫نفــي دعــوى املدعــي وحيــث لــم يقبــل املدعــي بيمــن املدعــى عليــه لــذا‬\n      ‫فقــد حكمــت بصــرف النظــر عــن طلــب املدعــي يف دعــواه باســترداد‬\n      ‫حيــازة الشــيك محــل الدعــوى وأفهمتــه مبــا يلــي ‪:‬ـ أوالً‪ :‬أن لــه ميني املدعى‬\n      ‫عليــه متــى مــا طلبهــا علــى نفــي دعــواه ثاني ـ ًا ‪ :‬أن لــه احلــق باملطالبــة يف‬\n      ‫احملكمــة املختصــة باملوضــوع املالــي للشــيك محــل الدعــوى وبعــرض‬\n      ‫احلكــم علــى املدعــي قــرر عــدم قناعتــه باحلكــم وطلــب االســتئناف‬\n      ‫فجــرى إفهامــه مبقتضــى التعليمــات يف ذلــك بــأن عليــه مراجعــة‬\n      ‫احملكمــة يــوم األربعــاء تاريــخ ‪1434/01/29 :‬ه ـ لتقــدمي الئحتــه‬\n      ‫االعتراضيــة وأن عليــه إعادتــه مــع الالئحــة االعتراضيــة خــال مــدة ال‬\n      ‫تتجــاوز الثالثــن يوم ـ ًا وأنــه إذا تأخــر عــن ذلــك ســوف يســقط حقــه يف‬\n      ‫االســتئناف كمــا أنــه إذا تأخــر عــن تاريــخ موعــد اســتالم الصــك ســوف‬\n      ‫حتســب عليــه مــدة التأخيــر مــن مــدة الثالثــن يوم ـ ًا املذكــورة ففهــم‬\n      ‫وعلــى جميــع مــا تقــدم حصــل التوقيــع مــن اجلميــع واهلل املوفــق حتريــرا‬\n      ‫يف‪1434/01/25 :‬ه ـ وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n                                                                           ‫وصحبه وسلم ‪.‬‬\n      ‫احلمد هلل وحده وبعد ‪ . . .‬فقد اطلعن ــا نحن قـض ــاة الدائ ــرة احلقوقية‬\n      ‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n      ‫لــدى احملكمــة برقــم ‪ 34713837‬وتاريــخ ‪1434/3/22‬ه ـ الــواردة مــن‬\n\n\n‫‪197‬‬\n\f‫فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة االحســاء الشــيخ‪......./‬‬\n‫برقــم ‪ 332213420‬وتاريــخ ‪1434/3/16‬ه ـ املرفــق بهــا الصــك الصــادر‬\n‫مــن فضيلتــه املســجل برقــم ‪ 3422009‬وتاريــخ ‪1434/1/25‬ه ـ بشــأن‬\n‫دعوى‪......./‬ضــد‪......./‬يف قضيــة حقوقيــة وقــد تضمــن الصــك حكــم‬\n‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة الصــك وصــورة ضبطــه‬\n‫والالئحــة االعتراضيــة وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم‬\n‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف‬\n                                                             ‫‪1434/3/29‬هـ‪.‬‬\n\n\n\n\n                                                                                 ‫‪198‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":186,"source_page_end":198,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"a714425623accd4913096cfbc8e3ebd9c5c1ee53512c7b8af5184fdec21ebed3","normalized_text_hash":"4e467d137a9d3a07eff4182371b7e0f841d69c47d0c988cbd6141b4b429ecd59","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p186-3422009"},{"id":"caecce48-1902-59cd-ad4a-d286fcfcc197","document_type":"judgment","category":"judicial","subcategory":"general","title":"شراكة -مضاربة -تسليم مال للغير ألجل املضاربة -دفع املضارب املال إلى غيره ليضارب به من غير اذن رب املال -تعد يوجب الضمان -تفريط املضارب -حكم بتضمن مضارب لتعديه وتفريطه - يشترط لصحة القراض تقدير نصيب العامل من الربح -حكم القراض الفاسد -تهميش على الصك بالسداد .","document_number":"34238180","case_number":"34156169","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف ف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/12","year":"1434","subject":"شراكة -مضاربة -تسليم مال للغير ألجل املضاربة -دفع املضارب املال إلى غيره ليضارب به من غير اذن رب املال -تعد يوجب الضمان -تفريط املضارب -حكم بتضمن مضارب لتعديه وتفريطه - يشترط لصحة القراض تقدير نصيب العامل من الربح -حكم القراض الفاسد -تهميش على الصك بالسداد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1434/6/12 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪34238180 :‬‬\n                        ‫َر ْق ُم الدعوى‪34156169 :‬‬\n‫رقم قرار التصديق من محكمة االستئناف‪34832347 :‬‬\n                           ‫تاريخه‪1434/7/5:‬هـ‬\n\n\n       ‫شــراكة ‪ -‬مضاربــة ‪ -‬تســليم مــال للغيــر ألجــل املضاربــة ‪ -‬دفــع املضارب‬\n       ‫املــال إلــى غيــره ليضــارب بــه مــن غيــر اذن رب املال ‪ -‬تعــدٍ يوجب الضمان‬\n       ‫‪ -‬تفريــط املضــارب ‪ -‬حكــم بتضمــن مضــارب لتعديــه وتفريطــه ‪-‬‬\n       ‫يشــترط لصحــة القــراض تقديــر نصيــب العامــل مــن الربــح ‪ -‬حكــم‬\n                          ‫القــراض الفاســد ‪ -‬تهميــش علــى الصــك بالســداد ‪.‬‬\n\n\n\n\n       ‫‪ -1‬يشــترط لصحــة القــراض تقديــر نصيــب العامــل مــن الربــح نــص‬\n                             ‫عليــه يف املغنــي (‪ - 14/7‬كشــاف القنــاع ‪.) 499/8‬‬\n       ‫‪ -2‬حكــم القــراض الفاســد فســخه ورد املــال الــى صاحبــه والربــح لــه‬\n       ‫والوضعيــة عليــه نــص عليــه يف (بدايــة املجتهــد ‪ - 182/2‬كشــاف‬\n                                                                    ‫القنــاع ‪.) 500/8‬‬\n       ‫‪ -3‬اتفــاق اهــل العلــم علــى ان املقــارض مؤمتــن ال ضمــان عليــه فيمــا‬\n       ‫يتلفــه مــن املــال مــن غيــر جنايــة منــه فيــه وال اســتهالك لــه وال تضييــع‬\n       ‫هــذه ســبيل األمانــة وســبيل األمنــاء حــكاه ابــن عبــد البــر (االســتذكار‬\n       ‫‪ ) 124/21‬وابن رشــد (بداية املجتهد ‪ )178/2‬وكشــاف القناع للبهوتي‬\n                                                                              ‫(‪.)524/8‬‬\n       ‫‪ -4‬قــال ابــن قدامــه يف املغنــي (‪( : )156/7‬فصــل ‪ :‬وليــس للمضــارب‬\n       ‫دفــع املــال الــى آخــر مضاربــه‪ .‬نــص عليــه أحمــد يف روايــة األثــرم وحــرب‬\n                                  ‫وعبــداهلل قــال ‪ :‬إن أذن لــه رب املــال وإال فــا )‪.‬‬\n‫‪199‬‬\n\f‫دعــوى املدعــي ضــد املدعــى عليــه انــه ســلم للمدعــى عليــه مبلغــا قــدره‬\n‫اربعمائــة الــف ريــال لغــرض املتاجــرة واملضاربــة بهــا يف ســوق األســهم‬\n‫وانــه لــم يتفــق معــه علــى نســبة أربــاح معينــة وقــرر انــه طالــب املدعــى‬\n‫عليــه بــأن يــرد اليــه رأس مالــه إال أنــه أخــذ يف املماطلــة والتأجيــل وطالــب‬\n‫املدعــي إلــزام املدعــى عليــه بدفــع رأس املــال حــاال وقــدره أربعمائــة الــف‬\n‫ريــال واألربــاح إن وجــدت ‪ ،‬أجــاب املدعــى عليــه بــأن مــا ذكــره املدعــي‬\n‫ا إال مبلغـ ًا‬\n             ‫صحيــح وأنــه تعــرض للخســارة وأنــه لــم يبــق مــن املبلــغ كامـ ً‬\n    ‫قــدره مائــة وثالثــة آالف ومئتــان ريــال اســتعد بدفعهــا حــاال للمدعــي ‪.‬‬\n‫‪ ،‬قــرر املدعــى عليــه أنــه ســبق ان ســلم للمدعــى مبلغــا قــدره ثالثــون‬\n‫الــف ريــال مــن املبلــغ املدعــى بــه‪ ،‬قــرر املدعــي مصادقتــه علــى اســتالم‬\n‫ثالثــن الــف ريــال وانهــا كانــت اربــاح‪ ،‬كمــا قــرر املدعــي مصادقتــه‬\n‫علــى خســارة املدعــى عليــه وطالــب بــرد رأس املــال‪ ،‬قــرر املدعــى‬\n‫عليــه انــه ســلم مبلــغ املضاربــة الــى مضــارب آخــر ليتاجــر لــه بــدون اذن‬\n‫ـاء علــى مــا هــو مقــرر عنــد الفقهــاء‬\n                                        ‫املدعــي‪ ،‬قــرر ناظــر القضيــة أنــه بنـ ً‬\n‫مــن أنــه ليــس للمضــارب دفــع املــال إلــى آخــر مضاربــة بــدون اذن صاحبــه‬\n‫وإلقــرار املدعــى عليــه باســتالم مبلــغ ثالثــن الــف ريــال املشــار اليهــا‬\n‫يف نــص القضيــة فقــد صــدر احلكــم بــأن يســلم املدعــى عليــه للمدعــي‬\n‫باقــي املبلــغ وقــدره ثالثمائــة وســبعون الــف ريــال‪ ،‬قــرر املدعــى عليــه‬\n‫عــدم القناعــة‪ ،‬صــدر قــرار محكمــة االســتئناف مبكــة املكرمــة‬\n‫باملصادقــة علــى احلكــم‪ ،‬حضــر املدعــي وقــرر أنــه اســتلم كامــل املبلــغ‬\n                                                                   ‫احملكــوم بــه ‪.‬‬\n\n                                                                                        ‫‪200‬‬\n\f      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي‬\n      ‫أنــا ‪ .......‬القاضــي باحملكمــة العامــة بالطائــف ففــي يــوم االربعــاء‬\n      ‫‪1434/5/1‬ه ـ الســاعة التاســعة والنصــف صباح ـ ًا بنــاء علــى الدعــوى‬\n      ‫احملالــة إلــي مــن فضيلة الرئيس برقم ‪ 34156169‬وتاريخ ‪1434/4/6‬هـ‬\n      ‫واملقيــدة باحملكمــة برقــم ‪ 3434347‬وتاريــخ ‪1434/4/6‬ه ـ أفتتحــت‬\n      ‫اجللســة وفيهــا حضــر املدعــي ‪ /‬اجلنســية مبوجــب اإلقامــة رقــم وحضــر‬\n      ‫حلضــوره املدعــى عليــه ‪ /‬ســعودي اجلنســية بالســجل املدنــي رقــم وأدعــى‬\n      ‫املدعــي قائــا يف دعــواه ‪ :‬إننــي أدعــي علــى احلاضــر معــي حيــث أنــه‬\n      ‫ســبق لــي يف عــام ‪2006‬م تقريب ـ ًا أن ســلمت للحاضــر مبلغ ـ ًا وقــدره‬\n      ‫أربعمائــة ألــف ريــال لغــرض املتاجــرة بهــا واملضاربــة بهــا بســوق األســهم‬\n      ‫ولــم أتفــق معــه علــى نســبة أربــاح معينــة ثــم ملــا طالبــت هــذا املدعــى عليــه‬\n      ‫بــرد رأس املــال أخــذ يف املماطلــة والتأجيــل يــوم بعــد يــوم لــذا أطلــب‬\n      ‫إلزامــه بدفــع رأس املــال لــي حــا ًال وقــدره أربعمائــة ألــف ريــال واألربــاح‬\n      ‫إن وجــدت وأنــي أســأله اجلــواب هــذه دعــواي‪ .‬وبســؤال املدعــى عليــه عــن‬\n      ‫دعــوى املدعــي أجــاب قائــا كل مــا ذكــره املدعــي يف دعــواه فكلــه‬\n      ‫ا إال أنــي وبحســب االتفــاق بينــي وبينــه شــغلتها يف‬ ‫صحيــح جملــة وتفصيـ ً‬\n      ‫ا إال مبلــغ‬ ‫ســوق االســهم و تعرضــت للخســارة ولــم يبــق مــن املبلــغ كامـ ً‬\n      ‫قــدره مائــة وثالثــة أالف ومئتــان ريــال ومســتعد بدفعهــا لــه حــا ًال وقــد‬\n      ‫ســبق وأن ســلمته مبلــغ ثالثــن ألــف ريــال مــن املبلــغ املدعــى بــه هكــذا‬\n      ‫ا ‪ :‬مــا ذكــر املدعــى عليــه‬   ‫أجــاب ‪ ،‬وبعرضــه علــى املدعــي أجــاب قائ ـ ً‬\n      ‫بأننــي اســتلمت مبلــغ ثالثــن ألــف ريــال فصحيــح لكنهــا كانــت أربــاح‬\n\n‫‪201‬‬\n\f‫هكــذا أجــاب‪ .‬ولضيــق وقــت اجللســة لدخــول اجللســة التــي تليهــا قــررت‬\n‫رفــع اجللســة وحتديــد موعــد جلســة جديــد يــوم االثنــن ‪1434/6/12‬ه ـ‬\n‫الســاعة التاســعة صباحـ ًا وعليــه جرى التوقيع وبــاهلل التوفيق وصلى اهلل‬\n ‫علــي ســيدنا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/5/1‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي يف احملكمــة العامــة‬\n‫بالطائــف ففــي يــوم اإلثنــن ‪ 1434/06/12‬ه ـ افتتحت اجللســة الســاعة‬\n‫التاســعة صباحــا وفيهــا حضــر املدعــي وحضــر حلضــوره املدعــى عليــه‬\n‫وبعــرض مــا ذكــره املدعــى عليــه مــن اخلســارة يف اجللســة الســابقة علــى‬\n‫املدعــي أجــاب قائـاً‪ :‬مــا ذكــره املدعــى عليــه مــن كونــه خســر يف هــذه‬\n‫املضاربــة فصحيــح وأنــا أطالبــه بــرد رأس املــال هكــذا قــرر‪ .‬ثــم جــرى‬\n‫ســؤال الطرفــن ‪ :‬عــن طبيعــة االتفــاق بينهمــا ؟ فأجــاب املدعــي ‪ :‬بأننــي‬\n‫دفعــت إليــه املبلــغ املذكــور أعــاه ليتجــر بــه ولــم أحــدد لــه ربحـ ًا معينــا‬\n‫هكــذا أجــاب‪ .‬وبعرضــه علــى املدعــى عليــه قــال ‪ :‬مــا ذكــره املدعــي‬\n‫فصحيــح ‪ ،‬هكــذا قــرر‪ ،‬ثــم جــرى ســؤال املدعــى عليــه عــن اخلســارة ؟‬\n‫ا ‪ :‬إننــي دفعــت مبلــغ املضاربــة إلــى مضــارب آخــر واســمه‬      ‫فأجــاب قائ ـ ً‬\n‫‪ .....‬ليتاجــر بهــا هكــذا أجــاب‪ ،‬وبســؤاله هــل أذن لــك رب املــال بذلــك؟‬\n‫أجــاب قائـاً‪ :‬إننــي لــم أرجــع إليــه يف هــذا التصــرف ‪ ،‬هكــذا أجــاب‪،‬‬\n‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة املتضمنــة مصادقــة املدعــى‬\n‫عليــه لدعــوى املدعــي واالطــاع علــى طيــات املعاملــة ومبــا أنــه يشــترط‬\n‫لصحــة القــراض تقديــر نصيــب العامــل مــن الربــح نــص عليــه يف (املغنــي‬\n‫‪ )140/7‬ويف (الكشــاف ‪ ، )499/8‬وألن حكــم القــراض الفاســد ‪:‬‬\n‫فســخه ورد املــال إلــى صاحبــه والربــح لــه والوضيعــة عليــه‪ ،‬نــص عليــه‬\n‫يف (بدايــة املجتهــد ‪ )182/2‬ويف كشــاف القنــاع (‪ ،)500/8‬وألن العقد‬\n\n\n                                                                                         ‫‪202‬‬\n\f      ‫الفاســد كصحيحــه مــن حيــث الضمــان وعدمــه والتفــاق أهــل العلــم‬\n      ‫علــى أن املقــارض مؤمتــن‪ ،‬ال ضمــان عليــه فيمــا يتلفــه مــن املــال مــن غيــر‬\n      ‫جنايــة منــه فيــه ‪ ،‬وال اســتهالك لــه ‪ ،‬وال تضييــع هــذه ســبيل األمانــة‬\n      ‫وســبيل األمنــاء حــكاه ابــن عبــد البــر (االســتذكار ‪ )124/21‬وابــن‬\n      ‫رشــد (بدايــة املجتهــد ‪ )178/2‬والبهوتــي (كشــاف القنــاع ‪، )524/8‬‬\n      ‫وألن دفــع املضــارب املــال إلــى غيــره ليضــارب بــه مــن غيــر إذن مــن رب‬\n      ‫املــال تعــد وتفريــط منــه ‪ ،‬وقــد ذكــر ابــن قدامــة يف املغنــي (‪:)156/7‬‬\n      ‫(فصــل ‪ :‬وليــس للمضــارب دفــع املــال إلــى آخــر مضاربــة ‪.‬نــص عليــه‬\n      ‫أحمــد ‪ ،‬يف روايــة األثــرم ‪ ،‬وحــرب ‪ ،‬وعبــد اهلل ‪ ،‬قــال ‪ :‬إن أذن لــه رب‬\n      ‫املــال ‪ ،‬وإال فــا )‪ ،‬وإلقــرار املدعــي باســتالمه مبلــغ ثالثــن ألــف ريــال‬\n      ‫مــن املدعــى عليــه لذلــك كلــه فقــد حكمــت بإلــزام املدعــى عليــه ‪ :‬أن‬\n      ‫يدفــع للمدعــي مبلــغ قــدره ثالثمائــة وســبعني ألــف ريــال حــا ًال هــذا مــا‬\n      ‫ظهــر لــي وبــه حكمــت ‪ ،‬وبعــرض احلكــم علــى املدعــى عليــه ‪ ،‬قــرر‬\n      ‫عــدم القناعــة وطلــب اســتئناف احلكــم بــدون الئحــة اعتراضيــة‪ ،‬وعليــه‬\n      ‫قــررت رفــع كامــل أوارق املعاملــة حملكمــة االســتئناف لتدقيقــه ‪،‬‬\n      ‫وبــاهلل التوفيــق‪ ،‬وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n      ‫أجمعــن‪ ،‬حــرر يف ‪1434/6/12‬هــ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n           ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/06/12‬ه ـ‬\n      ‫احلمــد هلل وحــده‪ ،‬والصــاة والســام علــى مــن ال نبــي بعــده‪ ،‬وبعــد ‪:‬‬\n      ‫ثــم عــادت املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة مصادقـ ًا‬\n      ‫عليهــا بالقــرار رقــم ‪34832347‬يف ‪1434/7/5‬ه ـ ونصــه احلمــد هلل‬\n      ‫والصــاة والســام علــى مــن ال نبــي بعــده وبعد فقد جــرى منا نحن قضاة‬\n      ‫االســتئناف بالدائــرة احلقوقيــة الســابعة مبحكمــة االســتئناف مبنطقــة‬\n\n\n‫‪203‬‬\n\f‫مكــة املكرمــة اإلطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة بالطائــف برقــم ‪ 34832347‬وتاريــخ ‪1434/6/19‬ه ـ‬\n‫املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ ‪ /‬القاضــي باحملكمــة‬\n‫العامــة بالطائــف واملســجل برقــم ‪ 34238180‬وتاريــخ ‪1434/6/12‬ه ـ‬\n‫املتضمــن دعــوى ‪ /‬ســوري اجلنســية ضــد‪ /‬وبدراســة الصــك وصــورة‬\n‫ضبطــه تقــررت املوافقــة علــي احلكــم واهلل املوفــق وصلــى اهلل علــى‬\n‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم قاضــي اســتئناف ختــم وتوقيــع‪.‬‬\n‫قاضــي اســتئناف ختــم وتوقيــع‪ .‬رئيــس الدائــرة ختــم وتوقيــع‪ .‬وصلــى اهلل‬\n                       ‫وســلم علــى نبينــا محمــد ‪.‬حــرر يف ‪1434/7/22‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده‪ ،‬وبعــد ‪ :‬ففــي يــوم اخلميــس ‪1434/11/6‬ه ـ افتتحــت‬\n‫اجللســة الســاعة الواحــدة ظهــرا بنــاء علــى االســتدعاء املقــدم مــن املدعو‪/‬‬\n‫واملقيــد باحملكمــة برقــم ‪ 342531883‬يف ‪1434/11/6‬ه ـ واملتضمــن‬\n‫رغبتــه يف التهميــش علــى الصــك رقــم ‪ 34238180‬يف ‪1434/6/12‬ه ـ‬\n‫ا وقــدره ثالثمائــة وســبعون ألــف‬ ‫باســتالمه املبلــغ املــدون بالصــك كامـ ً‬\n‫ريــال وحضــر فيهــا املدعــي ســوري اجلنســية مبوجــب اإلقامــة رقــم وقــرر‬\n‫أنــه اســتلم كامــل املبلــغ احملكــوم بــه ضــد املدعــى عليــه احملكــوم بــه‬\n‫باطــن هــذا الصــك ‪ ،‬وأنــه بعــد اســتالم املبلــغ ال يطالــب املدعــى عليــه‬\n‫وال غيــره بشــيء بخصــوص هــذه الدعــوى‪ ،‬وبهــذا انتهــت هــذه الدعــوى‪،‬‬\n‫وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد‪ .‬حــرر يف ‪1434/11/6‬ه ـ‬\n                                                                            ‫‪،،،‬‬\n‫احلمــد هلل وحــده‪ ،‬والصــاة والســام علــى مــن ال نبــي بعــده‪ ،‬وبعــد‪:‬ـ‬\n‫فقــد جــرى منــا نحــن قضــا َة الدائــرة احلقوقيــة الســابعة مبحكمــة‬\n‫االســتئناف يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة‬\n\n\n                                                                                    ‫‪204‬‬\n\f      ‫مــن فضيلــة رئيــس احملكمــة العامــة بالطائــف برقــم ‪34832347‬‬\n      ‫وتاريــخ ‪1434/06/19‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ‬\n      ‫القاضــي باحملكمــة العامــة بالطائف املســجل برقــم ‪ 34238180‬وتاريخ‬\n      ‫‪1434/06/12‬ه ـ املتضمــن دعــوى ســوري اجلنســية ضــد ‪ ،‬وبدراســة‬\n                      ‫الصــك وص ــورة ضبط ــه تق ــررت املوافق ــة عل ــى احلكــم‪.‬‬\n          ‫واهلل املوفق وصلـى اهلل علـى نبينا محمد وعلـى آلـه وصحبـه وسلم ‪.‬‬\n\n\n\n\n‫‪205‬‬\n\f206\n\f207\n\f208\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":199,"source_page_end":208,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"a0df928db0d730eae45737de3ec9e24765f5dbb45d4ae21c0bc552129203bc38","normalized_text_hash":"18f50fe40402cb15725ef2f7a3bb097311f27cb49f107e39287675304317c99b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p199-34238180"},{"id":"e71f7d43-a456-592d-8580-08a414856a2f","document_type":"judgment","category":"judicial","subcategory":"general","title":"ضمان -تكاليف عاج عامل مبؤسسة -عدم حضور ممثل للمدعى عليه -سند ضمان مصدق من جهة نظامية -إلزام بالدفع والغائب على حجته -إخطار الغائب بصورة من احلكم -تصديق محكمة","document_number":"33482391","case_number":"25038","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/29","year":"1434","subject":"ضمان -تكاليف عاج عامل مبؤسسة -عدم حضور ممثل للمدعى عليه -سند ضمان مصدق من جهة نظامية -إلزام بالدفع والغائب على حجته -إخطار الغائب بصورة من احلكم -تصديق محكمة","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33482391 :‬تاريخه‪1433/12/29 :‬هـ‬\n                             ‫رقم الدعوى‪25038 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 33479099‬تاريخه‪1433/12/27 :‬هـ‬\n\n\n       ‫ضمــان ‪ -‬تكاليــف عــاج عامــل مبؤسســة ‪ -‬عــدم حضــور ممثــل للمدعــى‬\n       ‫عليــه ‪ -‬ســند ضمــان مصــدق مــن جهــة نظاميــة ‪ -‬إلزام بالدفــع والغائب‬\n       ‫علــى حجتــه ‪ -‬إخطــار الغائــب بصــورة مــن احلكــم ‪ -‬تصديــق محكمــة‬\n                                                                 ‫االســتئناف ‪.‬‬\n\n\n\n\n                                ‫قول النبي صلى اهلل عليه وسلم‪« :‬الزعيم غارم»‪.‬‬\n\n\n\n\n       ‫تقدمــت املدعيــة «شــركة طبيــة» بدعــوى ضــد املدعــى عليهــا «مؤسســة»‬\n       ‫بــأن مصابــا يعمــل لــدى املؤسســة تلقــى العــاج باملستشــفى لديهــا وقــد‬\n       ‫ضمنتــه بتكاليــف عالجــه فتطلــب إلزامهــا بدفــع تكاليــف العالج ‪ ،‬لم‬\n       ‫حتضــر املدعــى عليهــا اجللســة رغــم تبلــغ وكيلهــا الشــرعي ‪ ،‬جــرى طلب‬\n       ‫البينــة مــن املدعيــة فأبــرز خطابــا مدونــا علــى مطبوعــات املدعــى عليهــا‬\n       ‫مضمونــه التزامهــا بدفــع تكاليــف عــاج العامــل لديهــا ‪ ،‬جــرى االطالع‬\n       ‫علــى خطــاب شــهادة تســجيل املؤسســة املدعــى عليهــا وخطــاب األمــارة‬\n       ‫بطلــب إحضارهــا ‪ ،‬عليــه وبنــاء علــى خطــاب الكفالة«الضمــان» املرفــق‬\n       ‫بــاألوراق املصــدق مــن الغرفــة التجاريــة وفواتيــر العــاج ولقــول النبــي‬\n       ‫صلــى اهلل عليــه وســلم «الزعيــم غــارم» فقــد قــررت الدائــرة احلكــم علــى‬\n\n‫‪209‬‬\n\f‫املدعــى عليهــا بدفــع تكاليــف العــاج حــاال للمدعيــة والغائــب علــى‬\n‫حجتــه متــى حضــر ‪ ،‬برفعــه حملكمــة االســتئناف عــاد احلكــم مصدقــا‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ..........‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالريــاض برقــم ‪ 25038‬وتاريــخ ‪ 1430/05/23‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 3078384‬وتاريــخ ‪ 1430/05/23‬ه ـ ويف هــذا‬\n‫اليــوم األربعــاء املوافــق‪ 1430/10/18‬ه ـ فتحــت اجللســة وفيهــا حضــر‬\n‫‪ ...............‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...............‬‬\n‫وكيــا عــن ‪...........‬بصفتــه رئيــس شــركة ‪ ...‬الطبيــة مبوجــب صــك‬\n‫الوكالــة الصــادر مــن كتابــة عــدل الريــاض الثانيــة برقــم ‪26274‬‬\n‫وتاريــخ ‪1429/3/14‬ه ـ رقــم اجللــد ‪ 16629‬املخــول فيــه باملرافعــة‬\n‫واملدافعــة واالقــرار وقبــول احلكــم واالعتــراض عليــه ولــم يحضــر احــد‬\n‫عــن املؤسســة املدعــى عليهــا رغــم تبلــغ وكيلهــا ‪ .............‬حتــى انتهــى‬\n‫وقتهــا احملــدد ولــذا رفعــت اجللســة ‪ .‬احلمــد هلل وحــده وبعــد يف يوم الثالثاء‬\n‫املوافــق ‪1432/03/26‬ه ـ فتحــت اجللســة وفيهــا حضــر املدعــي وكالــة‬\n‫ولــم يحضــر املؤسســة املدعــى عليهــا وجــرى ســؤال املدعــي وكالــة عــن‬\n‫دعــواه قــدم مذكــرة مكونــة مــن صفحــة واحــدة هــذا نصهــا إنــه يف‬\n‫يــوم ‪2008/05/13‬م املوافــق ‪1429/05/08‬ه ـ دخــل املصــاب ‪.........‬‬\n‫(ســوري اجلنســيه) املستشــفى ‪ ...........‬للعــاج نتيجــة حــادث مــروري‬\n‫أدى الــى إصابــات متعــددة باجلســم وقــد أجريــت للمصــاب العمليــات‬\n‫اجلراحيــة الالزمــة ‪ ،‬ومت تقــدمي كافــة اخلدمــات الطبيــة ‪ ،‬وبلغــت‬\n                                                                                      ‫‪210‬‬\n\f      ‫تكاليــف عالجــه ‪ 109,504,68‬ريــال مائــة وتســعة آالف وخمســمائة‬\n      ‫وأربعــة ريــاالت وثمــان وســتني هللــه وقــد تعهــدت مؤسســة ‪ ...‬للتجــارة‬\n      ‫كونهــا كفيلــة املصــاب بســداد كافــة التكاليــف ‪ ،‬إال أنــه ومنــذ‬\n      ‫تاريــخ ‪2008/06/01‬م املوافــق ‪1429/05/27‬ه ـ وقســم التحصيــل‬\n      ‫لدينــا يتابــع املؤسســة لســداد تكاليــف العــاج وفــق التعهــد املقــدم منهــم‬\n      ‫والــذي التزمــت املؤسســة مبوجبــه بســداد التكاليــف ‪ ،‬ولكــن دون‬\n      ‫جــدوى حيــث مــازال مســؤولو املؤسســة مياطلــون بالســداد أطلــب احلكــم‬\n      ‫بإلــزام مؤسســة ‪ ...‬للتجــارة بســداد مســتحقات املستشــفى والبالغــة‬\n      ‫‪ 109,504,68‬ريــال مائــة وتســعة آالف وخمســمائة وأربعــة ريــاالت وثمــان‬\n      ‫وســتني هللــه انتهــى فســألت املدعــي وكالــة عــن العمليــات اجلراحيــة‬\n      ‫وأنواعهــا وأجــرة كل عمليــة فطلــب املهلــة يف إيضــاح ذلــك فأجيــب‬\n      ‫لطلبــه ورفعــت اجللســة لذلــك ‪ .‬احلمــد هلل وحــده وبعــد يف يــوم الســبت‬\n      ‫املوافــق ‪1433/01/22‬ه ـ فتحــت اجللســة وفيهــا حضــر املدعــي وكالــة‬\n      ‫ولــم يحضــر احــد عــن املؤسســة املدعــى عليهــا عنهــا وبســؤال املدعــي‬\n      ‫وكالــة عمــا طلــب املهلــة يف إحضــاره أبــرز ورقــة من مطبوعات املؤسســة‬\n      ‫املدعــى عليهــا ‪ .............‬مدونــا عليهــا مــا نصــه الســادة املستشــفى ‪..........‬‬\n      ‫بالريــاض ‪ ،‬الســام عليكــم ورحمــة اهلل وبركاتــه بهــذا نفيدكــم‬\n      ‫بأننــا نكفــل املريــض لديكــم الســيد ‪ ..........‬كفالــة أداء مبــا يترتــب‬\n      ‫عليــه لكــم مــن قيمــة العــاج علــى أثــر احلــادث املــروري وقدومــه إليكــم‬\n      ‫بتاريــخ ‪ 2008/5/13‬وبــذك نأمــل منكــم كفالتنــا هــذا شــاكرين‬\n      ‫ومقدريــن حســن تعاونكــم مــع متنياتنــا بالشــفاء العاجــل مذيــل بتوقيــع‬\n      ‫مؤسســة ‪ ............‬وختمهــا ومصــدق مــن الغرفــة التجاريــة انتهــى وبســؤاله‬\n      ‫هــل لديــه زيــادة بينــة قــال ليــس لــدي فرفعــت اجللســة للتأمــل ‪ .‬احلمــد هلل‬\n\n\n‫‪211‬‬\n\f‫وحــده وبعــد يف يــوم الثالثــاء املوافــق ‪1433/06/03‬ه ـ فتحــت اجللســة‬\n‫وفيهــا حضــر املدعــي وكالــة ولــم يحضــر احــد عــن املؤسســة املدعــى‬\n‫عليهــا وقــد طلــب مــن املدعــي وكالــة يف اجللســة الســابعة إيضــاح نــوع‬\n‫العمليــات وأجــرة كل عمليــة وبعــرض ذلــك علــى املدعــي وكالــة قــال‬\n‫أطلــب املهلــة فأجيــب لطلبــه ورفعــت اجللســة لذلــك ‪ .‬احلمــد هلل وحــده‬\n‫وبعــد فلــدي أنــا د‪ ............. .‬القاضــي يف احملكمــة العامــة بالريــاض‬\n‫واخللــف لفضيلــة الشــيخ ‪ ............‬ففــي يــوم اإلثنني املوافــق‪1433/11/29‬‬\n‫ه ـ افتتحــت اجللســة الســاعة ‪ 10 : 30‬وفيهــا حضــر املدعــي وكالــة ‪.......‬‬\n‫ولــم يحضــر احــد عــن املؤسســة املدعــى عليهــا وبعــرض مــا ســبق رصــده‬\n‫علــى املدعــي وكالــة صــادق عليــه وابــرز فواتيــر تفصيليــة بالعــاج‬\n‫الــذي تلقــاه املكفــول املصــاب ‪( ............‬ســوري اجلنســيه) ومجموعهــا‬\n‫مائــة وتســعة االف وخمســمائة واربعــة ريــاالت وثمــان وســتني هللــة‬\n‫كمــا جــرى الرجــوع إلــى كامــل اوراق املعاملــة ووجــد شــهادة تســجيل‬\n‫مؤسســة صــادر مــن وزارة التجــارة والصناعــة مكتــب الســجل التجــاري‬\n‫بالريــاض برقــم ‪ 1010154440‬وتاريــخ ‪1420/03/09‬ه ـ وهــي مؤسســة‬\n‫فرديــة باســم مؤسســة ‪ .............‬لصاحبهــا ‪ ..........‬ســعودي بالســجل‬\n‫املدنــي رقــم ‪ ................‬كمــا جــرى الرجــوع إلــى اخلطابــات املوجــه مــن‬\n‫فضيلــة الســلف لإلمــارة بطلــب إحضــار املدعــى عليهــا وخطــاب كفالــة‬\n‫املؤسســة املدعــى عليهــا ‪ .‬فبنــاء علــى مــا تقــدم مــن الدعــوى ومــا جــاء‬\n‫يف أوراق املعاملــة وخطــاب الكفالــة املذكــور املصــدق مــن الغرفــة‬\n‫التجاريــة وفواتيــر العــاج ولقولــه صلــى اهلل عليــه وســلم ( الزعيــم غــارم‬\n‫) لذلــك كلــه فقــد حكمــت علــى املؤسســة املدعــى عليهــا بــإن تدفــع‬\n‫للمستشــفى املدعــي املبلــغ املدعــى بــه والبالــغ قــدره مائــة وتســعة االف‬\n\n\n                                                                                      ‫‪212‬‬\n\f      ‫وخمســمائة وأربعــة ريــاالت وثمــان وســتني هللــة وبذلــك حكمت ‪.‬وســيتم‬\n      ‫مبشــيئة اهلل تزويــد املؤسســة املدعــى عليهــا بصــورة مــن صــك احلكــم‬\n      ‫حســب املتبــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                     ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1433/11/29‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق‪ 1434/02/27‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 01 : 10‬هــذا وقــد مت بعــث صــورة مــن صــك‬\n      ‫احلكــم إلدارة احملضريــن باحملكمــة بخطابنــا رقــم ‪ 3429858‬يف‬\n      ‫‪1434/01/05‬ه ـ لتســليم صــورة الصــك للمؤسســة املدعــى عليهــا ومت‬\n      ‫رفــض االســتالم بســبب عــدم وجــود كروكــي للموقــع وجــرى االتصــال‬\n      ‫علــى املدعــي إلحضــار الكروكــي املطلــوب فلــم يــرد علــى االتصــال‬\n      ‫بنــاء علــى احملضــر املعــد مــن قبــل ســعادة املشــرف االدراي يف املكتــب‬\n      ‫املــؤرخ يف ‪1434/02/25‬ه ـ لــذا تقــرر بعث املعاملة حملكمة االســتئناف‬\n      ‫املوقــرة واملدعــى عليــه الغائــب علــى حجتــه متــى حضــر وبــاهلل التوفيــق‬\n      ‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n      ‫‪1434/02/27‬ه ـ هــذا وقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n      ‫بالريــاض برقــم ‪ 332171056‬وتاريــخ ‪1434/01/04‬ه ـ املرفــق بهــا‬\n      ‫قــرار التصديــق الصــادر مــن الدائــرة احلقوقيــة الثانيــة برقــم ‪33479099‬‬\n      ‫وتاريــخ ‪1433/12/27‬ه ـ ونــص احلاجــة منــه بعــد املقدمــة ‪ (:‬وحيث ســبق‬\n      ‫دارســة الصــك وصــورة ضبطــه وأوراق املعاملــة وباالطــاع علــى مــا أجاب‬\n      ‫بــه فضيلــة القاضــي اخللــف بنــاء علــى قرارنــا رقــم ‪ 33387546‬وتاريــخ‬\n      ‫‪1433/8/20‬ه ـ لــم يظهــر مــا يوجــب النقــض بعــد اإلجــراء االخيــر‬\n      ‫وبــاهلل التوفيــق ) ‪.‬وقــد همــش مبضمونــه علــى ظهــر الصــك وامــرت بنقــل‬\n      ‫ذلــك يف ضبطــه وســجله احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن‬\n\n\n‫‪213‬‬\n\f‫قضــاة الدائــرة الثالثــة لتمييــز القضايــا احلقوقيــة مبحكمــة االســتئناف‬\n‫بالريــاض علــى املعاملــة الــواردة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بالريــاض املســاعد باخلطــاب رقــم ‪ 3157902‬وتاريــخ ‪1434/4/22‬ه ـ‬\n‫املرفــق بهــا الصــك رقــم ‪ 33482391‬وتاريــخ ‪1433/12/29‬ه ـ الصــادر‬\n‫مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪ ............‬املتضمــن احلكــم يف‬\n‫الدعــوى املقامــة مــن ‪ ............‬ضــد ‪ .............‬علــى النحــو املوضــح بالصــك‬\n‫واملتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل بــه وبدراســة الصــك‬\n‫وصــورة ضبطــه وأوراق املعاملــة تقــرر الدائــرة املصادقــة علــى احلكــم ‪.‬‬\n       ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                         ‫‪214‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":209,"source_page_end":214,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"89139aee575a6d1f559c9aea55dd529a9f66920f62955d446022f5faeb3d85f9","normalized_text_hash":"bcbfabbb6506bccd54fa35b2fc775c28c592e5d45f56f4e56f64b308a09317be","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p209-33482391"},{"id":"8e8f15db-4981-5dc8-93f0-4ac6444dd71d","document_type":"judgment","category":"judicial","subcategory":"general","title":"كفالة -كفالة حضورية -إمهال الكفيل مدة زمنية إلحضار مكفوله -تعذر إحضار املكفول على الكفيل -الكفالة نوع من الضمان -غياب الكفيل عن اجللسة وصدور حكم حضوري ضده - حكم على الكفيل بتسديد ما بذمة املكفول لتعذر إحضاره -إفهام الكفيل بأن له مطالبة مكفوله بدعوى مستقلة -إخطار الكفيل الغائب بصورة من احلكم .","document_number":"3420453","case_number":"33497030","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/24","year":"1434","subject":"كفالة -كفالة حضورية -إمهال الكفيل مدة زمنية إلحضار مكفوله -تعذر إحضار املكفول على الكفيل -الكفالة نوع من الضمان -غياب الكفيل عن اجللسة وصدور حكم حضوري ضده - حكم على الكفيل بتسديد ما بذمة املكفول لتعذر إحضاره -إفهام الكفيل بأن له مطالبة مكفوله بدعوى مستقلة -إخطار الكفيل الغائب بصورة من احلكم .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 3420453 :‬تاريخه ‪1434/1/24 :‬هـ‬\n                        ‫رقم الدعوى‪33497030 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34239456‬تاريخه‪1434/6/13 :‬هـ‬\n\n\n      ‫كفالــة ‪ -‬كفالــة حضوريــة ‪ -‬إمهــال الكفيــل مــدة زمنيــة إلحضــار‬\n      ‫مكفولــه ‪ -‬تعــذر إحضــار املكفــول علــى الكفيــل ‪ -‬الكفالــة نــوع مــن‬\n      ‫الضمــان ‪ -‬غيــاب الكفيــل عــن اجللســة وصــدور حكــم حضــوري ضــده ‪-‬‬\n      ‫حكــم علــى الكفيــل بتســديد مــا بذمــة املكفــول لتعــذر إحضــاره ‪ -‬إفهــام‬\n      ‫الكفيــل بــأن لــه مطالبــة مكفولــه بدعــوى مســتقلة ‪ -‬إخطــار الكفيــل‬\n                                                      ‫الغائــب بصــورة مــن احلكــم ‪.‬‬\n\n\n\n\n      ‫‪ -1‬مــا ورد يف صحيــح البخــاري مــن حديــث أبــي هريــرة يف قصــة‬\n      ‫اإلســرائيلي الــذي اســتلف مــن رجــل الــف دينــار وقــال ائتنــى بشــهود‬\n      ‫وقــال كفــى بــاهلل شــهيدا قــال فإتنــى بكفيــل قــال كفــى بــاهلل كفيــا‬\n                             ‫وقــد ترجــم لــه البيهقــي «بــاب يف الكفالــة بالبــدن»‬\n      ‫‪ -2‬قــال صاحــب احلاشــية علــى الــروض املربــع « وان تعــذر إحضــار‬\n      ‫املكفــول علــى الكفيــل بــأن اختفــى أو امتنــع أو غيــر ذلــك بحيــث تعــذر‬\n      ‫إحضــاره مــع بقــاء حياتــه ضمــن كفيــل مــا عليــه مــن الديــن أو عــوض‬\n      ‫العــن وكــذا ان امتنــع الكفيــل عــن إحضــاره لزمــه مــا عليــه» (‪.) 113/5‬‬\n      ‫‪ -3‬قــال ابــن رجــب يف قواعــده ‪ (:‬إذا قضــى دين ـ ًا واجب ـ ًا بغيــر إذنــه‬\n      ‫فإنــه يرجــع بــه عليــه يف اصــح الروايتــن وهــي املذهــب عنــد اخلرقــي)‬\n                                                                          ‫(ص‪. )336‬‬\n\n\n‫‪215‬‬\n\f‫ادعــى املدعــي أنــه اقــرض شــخصا مبلغــا قــدره مائــة وســته وعشــرون‬\n‫ألــف ريــال قرضــا حســنا وقــد اشــترط علــى املقتــرض املذكــور حتــى‬\n‫حضوريــا يلتــزم بإحضــار املقتــرض عنــد‬‫ً‬        ‫ا‬‫يقرضــه أن يحضــر لــه كفيـ ً‬\n‫مطالبتــه بالقــرض ‪ ،‬فقــام املقتــرض بإحضــار املدعــى عليــه والتــزم‬\n‫املدعــى عليــه مبحــض إرادتــه أن يحضــر املقتــرض عنــد طلبــه ‪ ،‬وانــه‬\n‫طالــب املدعــى عليــه بإحضــار املقتــرض فلــم يجــد منــه جتاوبــا وطلــب‬\n‫املدعــى احلكــم علــى املدعــى عليــه بإحضــار املقتــرض وإذا لــم يحضــره‬\n‫فيحكــم عليــه بســداد مــا بذمــة املقتــرض ‪ ،‬أجــاب املدعــى عليــه‬\n‫باملصادقــة علــى الدعــوى وطلــب مهلــة إلحضــار املقتــرض ‪ ،‬يف جلســة‬\n‫أخــرى حضــر املدعــي ولــم يحضــر املدعــى عليــه وال مــن ميثلــه وبنــاء علــى‬\n‫مــا تقــدم وإلقــرار املدعــى عليــه بالدعــوى ولتخلفــه عــن احلضــور وملــا‬\n‫جــاء يف حيثيــات احلكــم والن الكفالــة نــوع مــن الضمــان فقــد صــدر‬\n‫احلكــم علــى املدعــى عليــه بــأن يســلم للمدعــي املبلــغ املدعــى بــه وان لــه‬\n‫مطالبــة املكفــول بدعــوى مســتقلة ‪ ،‬تقــرر إبــاغ املدعــى عليــه بنســخة‬\n‫مــن احلكــم ‪ .‬صــدر قــرار محكمــة االســتئناف باملوافقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضي يف احملكمة العامة مبكة‬\n‫املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة مبكــة املكرمــة برقــم ‪ 33497030‬وتاريــخ ‪1433/07/30‬‬\n‫ه ـ املقيــدة باحملكمــة برقــم ‪ 331440359‬وتاريــخ ‪ 1433/07/30‬ه ـ‬\n                                                                                      ‫‪216‬‬\n\f      ‫املتعلقــة بدعــوى‪ ...‬ضــد‪ ...‬ففــي هــذا اليــوم األربعــاء ‪1433/11/17‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 11 : 00‬وفيهــا حضــر بنغالــي اجلنســية مبوجــب‬\n      ‫اإلقامــة رقــم‪ ...‬وحضــر حلضــوره املدعــى عليــه‪ ...‬باكســتاني اجلنســية‬\n      ‫مبوجــب اإلقامــة رقــم ‪ ....‬ثــم ســألت املدعــي عــن دعــواه فأدعــى قائــا‬\n      ‫أنــي أقرضــت املدعــو مبلــغ مــن املــال قــدره مائــة و ســتة و عشــرون ألــف‬\n      ‫ريــال قرضــا حســنا و ذلــك بتاريــخ ‪1428‬ه ـ وقد اشــترطت علــى املقترض‬\n      ‫املذكــور حتــى أقرضــه أن يأتينــي بكفيــل حضــوري يلتــزم بإحضــاره‬\n      ‫وقــت مطالبتــي مبالــي فأتــى هــذا املدعــى عليــه والتــزم مبحــض إرادتــه‬\n      ‫أن يحضــر لــي املدعــو‪ ...‬عنــد طلبــي وهــا أنــذا أطالبــه بإحضــاره فلــم‬\n      ‫أجــد منــه جتاوبــا لــذا فأنــي أطلــب احلكــم علــى هــذا املدعــى عليــه‬\n      ‫بإحضــار املقتــرض إنفــاذ ملقتضــى كفالتــه وإن لــم يقــم بإحضــاره‬\n      ‫فأطلــب احلكــم بإلزامــه بدفــع كامــل املبلــغ املذكــور هــذه دعــواي‬\n      ‫و أســأله اجلــواب وبعــرض ذلــك علــى املدعــى عليــه أجــاب بقولــه قائــا‬\n      ‫إن مــا ورد يف دعــواه صحيــح فلقــد قمــت بكفالــة املدعــو‪ ...‬كفالــة‬\n      ‫حضوريــه عنــد طلــب املدعــي إحضــاره و ال أنكــر ذلــك ولكنــي أطلــب‬\n      ‫مهلــه إلحضــار املذكــور يف اجللســة القادمــة هكــذا قــال وبعــرض ذلــك‬\n      ‫علــى املدعــي أجــاب بقولــه أنــه ال مانــع لــدي مــن إعطــاء املدعــى عليــه‬\n      ‫مهلــه إلحضــار‪ ...‬هكــذا قــال ويف اليــوم الثالثــاء ‪1434/01/13‬ه ـ‬\n      ‫افتتحــت اجللســة وفيهــا حضــر املدعــي ولــم يحضــر املدعــى عليــه وال مــن‬\n      ‫ميثلــه فبنــاء علــى مــا تقــدم مــن الدعــوى وإلقــرار املدعــى عليــه بكفالــة‬\n      ‫املدعــو ‪ .... /‬كفالــة حضوريــة عنــد طلــب املدعــي إحضــاره ولطلبــه‬\n      ‫مهلــة إلحضــاره يف هــذا اليــوم ولتخلفــه عــن احلضــور وملــا ورد يف صحيــح‬\n      ‫البخــاري مــن حديــث أبــي هريــرة يف قصــة اإلســرائيلي الــذي اســتلف‬\n\n\n‫‪217‬‬\n\f‫مــن رجــل ألــف دينــار وقــال ائتنــي بشــهود قــال كفــى بــاهلل شــهيدا قــال‬\n‫فأتنــي بكفيــل قــال كفــى بــاهلل كفيــا وقــد ترجــم لــه البيهقــي (بــاب‬\n‫يف الكفالــة بالبــدن) وبهــذا القــول قــال مالــك وأبــو حنيفــة وهــو املرجــح‬\n‫عنــد الشــافعية وحــكاه ابــن رشــد عــن جمهــور فقهــاء األمصــار وعلــى‬\n‫الصحيــح مــن املذهــب إن تعــذر علــى الكفيــل إحضــار املكفــول ضمــن‬\n‫مــا عليــه وهــو اختيــار الشــيخ وقــال صاحــب احلاشــية علــى الــروض املربــع‬\n‫(وإن تعــذر إحضــار املكفــول علــى الكفيــل بــأن اختفــى أو امتنــع أو‬\n‫غيــر ذلــك بحيــث تعــذر إحضــاره مــع بقــاء حياتــه ضمــن كفيــل مــا عليــه‬\n‫مــن الديــن أو عــوض العــن وكــذا إن امتنــع الكفيــل مــن إحضــاره‬\n‫لزمــه مــا عليــه) ‪ 113/5‬وملــا قالــه ابــن رجــب يف قواعــده (إذا قضــي عنــه‬\n‫دينــا واجبــا بغيــر إذنــه فإنــه يرجــع بــه عليــه يف أصــح الروايتــن وهــي‬\n‫املذهــب عنــد اخلرقــي) صحيفــة ‪ 336‬وألن الكفالــة نــوع مــن الضمــان‬\n‫بنــاء علــى ذلــك فقــد حكمــت علــى املدعــى عليــه ‪ ...‬بــأن يدفــع للمدعــي‬\n‫املبلــغ املدعــى بــه وقــدره مائــة وســتة وعشــرون ألــف ريــال وأن لــه مطالبــة‬\n‫مكفولــه بدعــوى مســتقلة متــى رغــب يف ذلــك ومبــا تقــدم حكمــت‬\n‫واعتبرتــه حضوريــا يف حــق املدعــى عليــه وســوف يتــم إبالغــه بنســخة‬\n‫منــه لتقــدمي مــا لديــه حيالــه خــال ثالثــن يومــا مــن تاريــخ االســتالم فــإن‬\n‫لــم يفعــل خاللهــا فــإن حقــه يف االعتــراض يســقط ويكتســب احلكــم‬\n‫القطعيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                  ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/01/13‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ....‬القاضــي باحملكمــة العامــة مبكــة‬\n‫املكرمــة خلــف فضيلــة الشــيخ القاضــي األســبق بهــذه احملكمــة‬\n‫حيــث عــادت أوراق املعاملــة مــن محكمــة االســتئناف باخلطــاب‬\n\n\n                                                                                        ‫‪218‬‬\n\f      ‫رقــم ‪ 331440359‬يف ‪1434/6/19‬ه ـ رفقهــا الصــك الشــرعي رقــم‬\n      ‫‪ 3420453‬يف ‪1434/1/24‬ه ـ مظهــر ًا عليــه بقــرار الدائــرة احلقوقيــة‬\n      ‫الثانيــة مبحكمــة االســتئناف مبكــة املكرمــة رقــم ‪ 34239456‬يف‬\n      ‫‪1434/6/13‬ه ـ املتضمــن أنــه بدراســة الصــك وصــورة ضبطــه والئحتــه‬\n      ‫االعتراضيــة تقــرر باألكثريــة املوافقــة علــى احلكــم قاضــي اســتئناف‬\n      ‫ختــم وتوقيــع ‪ ... / ...‬قاضــي اســتئناف ‪ ...‬ختــم ‪ ...‬وتوقيــع ‪ ...‬لــي وجهــة‬\n      ‫نظــر ‪ ...‬رئيــس الدائــرة ختــم وتوقيــع ‪ ...‬وصلــى اهلل علــى نبينــا محمــد‬\n                            ‫وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/7/12‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪ :‬فقــد‬\n      ‫جــرى منــا نحــن قضــاة االســتئناف بالدائــرة احلقوقيــة الثانيــة مبحكمــة‬\n      ‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن‬\n      ‫فضيلــة رئيــس احملكمــة العامــة مبكــة املكرمة برقــم ‪33/1440359‬‬\n      ‫وتاريــخ ‪1434/5/27‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ‬\n      ‫القاضــي باحملكمــة العامــة مبكــة املكرمة واملســجل بعدد ‪3420453‬‬\n      ‫وتاريــخ ‪1434/1/24‬هـ ـ واملتضمــن دعــوى‪ /‬ضــد‪ /‬واحملكــوم فيــه مبــا‬\n                                                                         ‫دون باطنــه ‪.‬‬\n      ‫وبدراســة احلكــم وصــورة ضبطــه تقــرر باألكثريــة املوافقــة علــى‬\n      ‫احلكــم واهلل املوفــق‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                               ‫وســلم ‪.‬‬\n\n\n\n\n‫‪219‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":215,"source_page_end":219,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0f87b7923cd61249d2927b24284897eb0ee34a2ee7342e60a35c891148b655c7","normalized_text_hash":"379182e2e6a1999cd074023ea3c83e28f98d7677d5252e30e6b728902e6c3d9d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p215-3420453"},{"id":"1e0bf206-849c-5611-96e4-1ff300b1dc31","document_type":"judgment","category":"judicial","subcategory":"general","title":"كفالة غرم وأداء -بيع سيارة بأقساط -النص يف العقد على حلول كامل املبلغ حال التخلف عن سداد قسطني -عجز املكفول عن سداد األقساط احلا لة -مطالبة الكفيل بسداد كامل املبلغ -اشتراط حلول كامل األقساط عند العجز عن السداد ينايف مقتضى العقد -الضامن ال يطالب باملؤجل إال بعد حلوله - إلزام املدعى عليه (الكفيل) بتسليم املبلغ احلال -للكفيل مطالبة مكفوله بتخليصه من الكفالة -للكفيل مطالبة مكفوله مبا يسدده","document_number":"3425012","case_number":"3421853","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بحائل","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/2","year":"1434","subject":"كفالة غرم وأداء -بيع سيارة بأقساط -النص يف العقد على حلول كامل املبلغ حال التخلف عن سداد قسطني -عجز املكفول عن سداد األقساط احلا لة -مطالبة الكفيل بسداد كامل املبلغ -اشتراط حلول كامل األقساط عند العجز عن السداد ينايف مقتضى العقد -الضامن ال يطالب باملؤجل إال بعد حلوله - إلزام املدعى عليه (الكفيل) بتسليم املبلغ احلال -للكفيل مطالبة مكفوله بتخليصه من الكفالة -للكفيل مطالبة مكفوله مبا يسدده","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك‪ 3425012 :‬يف ‪1434/1/27‬هـ‬\n                   ‫رقم الدعوى‪3421853:‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 3453472‬تاريخه‪1434/3/2 :‬هـ‬\n\n\n‫كفالــة غــرم وأداء ‪ -‬بيــع ســيارة بأقســاط ‪ -‬النــص يف العقــد علــى‬\n‫حلــول كامــل املبلــغ حــال التخلــف عــن ســداد قســطني ‪ -‬عجــز‬\n‫املكفــول عــن ســداد األقســاط احلا ّلــة ‪ -‬مطالبــة الكفيــل بســداد كامــل‬\n‫املبلــغ‪ -‬اشــتراط حلــول كامــل األقســاط عنــد العجــز عــن الســداد‬\n‫ينــايف مقتضــى العقــد ‪ -‬الضامــن ال يطالــب باملؤجــل إال بعــد حلولــه ‪-‬‬\n‫إلــزام املدعــى عليــه (الكفيــل) بتســليم املبلــغ احلــال ‪ -‬للكفيــل مطالبــة‬\n‫مكفولــه بتخليصــه مــن الكفالــة‪ -‬للكفيــل مطالبــة مكفولــه مبــا يســدده‬\n\n\n\n\n       ‫فتوى اللجنة الدائمة للبحوث العلمية واإلفتاء ‪. 182-181/13‬‬\n\n\n\n\n‫ادعــى املدعــي ضــد املدعــى عليــه الكفيــل الغــارم يطالبــه بســداد مبلــغ‬\n‫وقــدره ثالثــة وخمســون ألف ـ ًا وخمســمائة ريــال ‪ ،‬حيــث بــاع املدعــي‬\n‫علــى مكفــول املدعــى عليــه ســيارة مببلــغ قــدره ســتون الــف ريــال وقــد‬\n‫ســدد املكفــول مبلغـ ًا قــدره ســتة آالف وخمســمائة ريــال وبقــي يف ذمتــه‬\n‫مبلــغ قــدره ثالثــة وخمســون ألف ـ ًا وخمســمائة ريــال احلــال منــه عشــرة‬\n‫آالف وخمســمائة ريــال اشــترط يف العقــد أنــه إذا تخلــف املشــتري عــن‬\n‫ا وقــد تخلــف املشــتري عــن قســطني فإن‬   ‫قســطني فــإن املبلــغ يحــل كامـ ً‬\n\n                                                                                   ‫‪220‬‬\n\f      ‫ا وقــد كفلــه املدعــى عليــه كفالــة‬   ‫املبلــغ املتبقــي يكــون حــا ًال كام ـ ً‬\n      ‫غــرم وأداء ويطالبــه بســداد املبلــغ حــاال ‪ ،‬صــادق املدعــى عليــه علــى‬\n      ‫دعــوى املدعــي ‪ ،‬مبــا أن املدعــي يطالــب املدعــى عليــه بحكــم ضمانــه‬\n      ‫للمشــتري يف كامــل قيمــة الســيارة وأن الســيارة مت بيعهــا علــى املشــتري‬\n      ‫باألقســاط وأن هنــاك شــرط ًا بينهمــا يتضمــن أنــه يف حالــة تخلــف‬\n      ‫املشــتري عــن ســداد قســطني فــإن كامــل قيمــة الســيارة تكــون حالــة‬\n      ‫وحيــث أن اللجنــة الدائمــة للبحــوث العلميــة واإلفتــاء قــد ســبق أن افتــت‬\n      ‫بشــأن حلــول املبالــغ املؤجلــة بكاملهــا دفعــة واحــدة إذا تخلــف املدين عن‬\n      ‫ســداد احلــال حيــث أفتــت اللجنــة بشــأن ذلــك بــأن هــذا غيــر صحيــح ألنــه‬\n      ‫ينــايف مقتضــى العقــد وهــو التأجيــل الــذي اســتحقت بــه الزيــادة ( فتــاوى‬\n      ‫اللجنــة الدائمــة ‪181/13‬و ‪ )182‬وحيــث أن احلــال الــذي تصــادق عليــه‬\n      ‫الطرفــان هــو مبلــغ قــدره عشــرة االف وخمســمائة ريــال ومعلــوم شــرع ًا‬\n      ‫أن الضامــن ملــزم شــرع ًا باحلــال وال يطالــب باملؤجــل إال بعــد حلولــه شــرح‬\n      ‫املنتهــى ‪ ، 252/2‬ملــا تقــدم صــدر احلكــم بإلــزام املدعــى عليــه أن يســلم‬\n      ‫للمدعــي املبلــغ احلــال مــن قيمــة الســيارة وقــدره عشــرة االف وخمســمائة‬\n      ‫ريــال وصــرف النظــر عــن باقــي مــا يطالــب بــه املدعــي لعــدم حلولــه ‪،‬‬\n      ‫إفهــام املدعــى عليــه بــأن لــه الرجــوع علــى مكفولــه ملطالبتــه بتخليصــه‬\n      ‫مــن ضمانــه كمــا لــه مطالبتــه مبــا يســلمه للمدعــي ‪ ،‬قنــع املدعــى عليــه‬\n      ‫باحلكــم واعتــرض املدعــي بالئحــة ‪ ،‬صــدق احلكــم مــن محكمــة‬\n                                                                            ‫االســتئناف ‪.‬‬\n\n\n\n\n‫‪221‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )...‬القاضــي يف احملكمــة العامــة‬\n‫بحائــل وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بحائــل املســاعد برقــم ‪ 3421853‬وتاريــخ ‪1434/01/13‬‬\n‫ه ـ املقيــدة باحملكمــة برقــم ‪ 34105095‬وتاريــخ ‪ 1434/01/13‬ه ـ‬\n‫ففــي يــوم الثالثــاء املوافــق‪ 1434/01/27‬ه ـ افتتحــت اجللســة الســاعة‬\n‫‪ 08 : 33‬وفيهــا حضــر ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ‪ ...‬وادعــى علــى احلاضــر معــه ‪ ...‬ســعودي بالســجل املدنــي رقــم‬\n‫‪...‬قائــا يف دعــواه لقــد بعــت علــى ‪...‬ســيارة مــن نــوع جيــب يف أكــس أر‬\n‫تويوتــا موديــل ‪1993‬م رقــم اللوحــة ‪ ......‬ورقــم الهيــكل ‪ ......‬مببلــغ قــدره‬\n‫ســتون ألــف ريــال وذلــك بتاريــخ ‪1433/6/2‬ه ـ وقــد ســدد املشــتري مــن‬\n‫قيمــة الســيارة ســتة أالف وخمســمائة ريــال وبقــي ثالثــة وخمســون ألف ـ ًا‬\n‫وخمســمائة ريــال واحلــال منهــا مبلغــا قــدره عشــرة أالف وخمســمائة ريــال‬\n‫ومــا لــم يحــل وقــدره ثالثــة وأربعــون الفـ ًا وخمســمائة ريــال فإنهــا تكــون‬\n‫حالــة مبوجــب العقــد حيــث أن العقــد قــد نــص علــى أنــه يف حالــة تخلــف‬\n‫ا يحــل وحيــث‬     ‫املشــتري عــن قســطني مــن األقســاط فــإن املبلــغ كام ـ ً‬\n‫ا يكــون حــا ًال مبلغـ ًا‬\n                         ‫أن املشــتري تخلــف عــن قســطني فــإن املبلــغ كامـ ً‬\n‫قــدره ثالثــة وخمســون الف ـ ًا وخمســمائة ريــال واملدعــى عليــه كفــل‬\n‫غرمــي يف كامــل قيمــة الســيارة أطلــب إلزامــه بســداد املبلــغ املتبقــي‬\n‫يف ذمــة املشــتري مبلغ ـ ًا قــدره ثالثــة وخمســون الف ـ ًا وخمســمائة ريــال‬\n‫وبســؤال املدعــى عليــه أجــاب قائــا مــا ذكــره املدعــي صحيــح جملــة‬\n‫و تفصيــا فقــد اشــترى ‪ ...‬مــن املدعــي هــذا احلاضــر الســيارة املوصوفــة‬\n\n\n                                                                                      ‫‪222‬‬\n\f      ‫يف ‪1433/6/2‬ه ـ مببلــغ قــدره ســتون الــف ريــال وقــد ســدد املشــتري مــن‬\n      ‫قيمــة الســيارة ســتة االف وخمســمائة ريــال وبقــي يف ذمــة املشــتري للبائــع‬\n      ‫مبلغــا قــدره ثالثــة وخمســون الفــا وخمســمائة ريــال واحلــال منهــا مبلغــا‬\n      ‫قــدره عشــرة االف وخمســمائة ريــال ومــا لــم يحــل وقــدره ثالثــة واربعــون‬\n      ‫الفــا وخمســمائة ريــال تكــون حالــة مبوجــب العقــد حيــث أن العقــد قــد‬\n      ‫نــص علــى أنــه يف حالــة تخلــف املشــتري عــن قســطني مــن األقســاط فــإن‬\n      ‫ا وأنــا كفيــل غرمــي للمشــتري يف كامــل قيمــة املبلغ‬     ‫املبلــغ يحــل كامـ ً‬\n      ‫وال مانــع لــدي مــن الســداد ولكنــي ال اســتطيع ســداد املبلــغ دفعــة واحدة‬\n      ‫هــذه إجابتــي وبعــد ســماع الدعــوى واإلجابــة وحيــث أن املدعــي يطالــب‬\n      ‫املدعــى عليــه بحكــم ضمانــه للمشــتري يف كامــل قيمــة الســيارة وأن‬\n      ‫الســيارة مت بيعهــا علــى املشــتري باألقســاط وأن هنــاك شــرط بينهمــا‬\n      ‫يتضمــن أنــه يف حالــة تخلــف املشــتري عــن ســداد قســطني فــإن كامــل‬\n      ‫قيمــة الســيارة تكــون حالــة وحيــث أن اللجنــة الدائمــة للبحــوث العلميــة‬\n      ‫واإلفتــاء قــد ســبق أن افتــت بشــأن حلــول املبالــغ املؤجلــة بكاملهــا دفعــة‬\n      ‫واحــدة إذا تخلــف املديــن عــن ســداد احلــال حيــث أفتــت اللجنــة بشــأن‬\n      ‫ذلــك بــأن هــذا غيــر صحيــح ألنــه ينــايف مقتضــى العقــد وهــو التأجيــل‬\n      ‫الــذي اســتحقت بــه الزيــادة ( فتــاوى اللجنــة الدائمــة ‪181/13‬و ‪182‬‬\n      ‫وحيــث أن احلــال الــذي تصــادق عليــه الطرفــان هــو مبلغ ـ ًا قــدره عشــرة‬\n      ‫االف وخمســمائة ريــال ومعلــوم شــرع ًا أن الضامــن ملــزوم شــرع ًا باحلــال‬\n      ‫وال يطالــب باملؤجــل إال بعــد حلولــه شــرح املنتهــى ‪ 252/2‬لذلــك كلــه‬\n      ‫فقــد الزمــت املدعــى عليــه أن يســلم للمدعــي املبلــغ احلــال مــن قيمــة‬\n      ‫الســيارة وقــدره عشــرة االف وخمســمائة ريــال وبــه حكمــت وصرفــت‬\n      ‫النظــر عــن باقــي مــا يطالــب بــه املدعــي لعــدم صحــة حلولــه وأفهمــت‬\n\n\n‫‪223‬‬\n\f‫املدعــى عليــه بــأن لــه الرجــوع علــى مكفولــه ملطالبتــه بتخليصــه مــن‬\n‫ضمانــه كمــا لــه مطالبتــه مبــا يســلمه للمدعــي وبإعــان احلكــم قــرر‬\n‫املدعــي عــدم القناعــة واســتعد بتقــدمي الئحــة فأفهــم بــأن عليــه املراجعــة‬\n‫يــوم غــد األربعــاء املوافــق ‪1434/1/28‬ه ـ الســاعة ‪ 11 : 00‬الســتالم‬\n‫نســخة احلكــم ولــه حــق املعارضــة خــال مــدة قدرهــا ثالثــون يومــا تبــدأ‬\n‫مــن تاريــخ اســتالمه يــوم غــد األربعــاء ‪1434/1/28‬ه ـ إذا مضــت املــدة‬\n‫ولــم يقــدم اعتراضــه خاللهــا فــإن احلكــم يكتســب القطعيــة كمــا قرر‬\n‫املدعــى عليــه القناعــة ورفعــت اجللســة يف الســاعة ‪ 9 : 00‬وعليــه حصــل‬\n‫التوقيــع وصلــى اهلل وســلم علــى نبينــا محمــد وآلــه وصحبــه أجمعــن‬\n                                                        ‫حــرر يف ‪1434/1/27‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة‬\n‫األولــى لتدقيــق القضايــا احلقوقيــة مبحكمــة االســتئناف مبنطقــة‬\n‫حائــل علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بحائــل‬\n‫املســاعد برقــم ‪ 34105095‬وتاريــخ ‪1434/2/5‬ه ـ واملقيــدة لدينــا برقــم‬\n‫‪ 34316612‬يف ‪1434/2/6‬ه ـ املرفــق بهــا الصــك رقــم ‪ 3425012‬يف‬\n‫‪1434/1/27‬ه ـ الصــادر مــن فضيلــة القاضــي ‪ ...‬اخلــاص بدعــوى ‪...‬ضــد‬\n‫‪...‬يف مطالبــة ماليــة علــى الصفــة املوضحــة يف الصــك وقــد حكــم‬\n‫فضيلتــه بإلــزام املدعــى عليــه بــأن يســلم للمدعــي املبلــغ احلــال مــن قيمــة‬\n‫الســيارة وقــدره عشــرة آالف وخمســمائة ريــال وبــه حكــم وصــرف‬\n‫النظــر عــن باقــي مــا يطالــب بــه لعــدم صحــة حلولــه وأفهــم املدعــي‬\n‫بــأن لــه الرجــوع علــى مكفولــه ملطالبتــه بتخليصــه مــن ضمانــه كمــا‬\n‫لــه مطالبتــه مبــا يســلمه للمدعــي وبدراســة الصــك وصــورة ضبطــه‬\n‫والالئحــة االعتراضيــة وأوراق املعاملــة ‪ :‬لــم يظهــر مــا يوجــب املالحظــة‬\n\n\n                                                                                       ‫‪224‬‬\n\f      ‫علــى مــا حكــم بــه فضيلتــه مــع تنبيــه فضيلتــه إلــى أنــه ورد يف جــواب‬\n      ‫املدعــى عليــه اســم املشــتري ‪ ... ...‬وهــذا غيــر صحيــح حيــث أن املشــتري‬\n      ‫‪...‬فعلــى فضيلتــه تصحيــح اســم املشــتري يف جــواب املدعــى عليــه وبــاهلل‬\n          ‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪225‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":220,"source_page_end":225,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"83ec4c670a6e10dd527905f18db722e33c7e08000f6fd5860e20820230c18477","normalized_text_hash":"b3d0906b46d0742843dfaba5bdb8e2d9129a17505c3c39ed738374ce145877af","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p220-3425012"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

